/**
 * Page transition management — DOM surgery for moving content
 * between adjacent page divs.
 *
 * Direct TypeScript port of vue-document-editor's
 * `imports/page-transition-mgmt.js` (MIT — Romain Lebesle).
 * Reference: https://github.com/motla/vue-document-editor
 *
 * Two functions:
 *   - move_children_forward_recursively: overflow path — pulls
 *     trailing children off the current page and prepends them to
 *     the next, with word-by-word text splitting and "s_tag"
 *     watermarking so a single block can have one half on page N
 *     and one half on page N+1.
 *   - move_children_backwards_with_merging: underfill path — pulls
 *     the first child of the next page back onto the current page,
 *     merging it into its same-s_tag sibling if one exists (so
 *     split blocks rejoin transparently).
 */

// Adds a non-standard `s_tag` field to DOM nodes — string watermark
// linking split halves of the same logical block across pages.
interface TaggedNode extends Node {
  s_tag?: string;
}
interface TaggedElement extends HTMLElement {
  s_tag?: string;
}

/**
 * Array.find on childNodes by their `s_tag` watermark.
 */
function findSubChildSiblingNode(
  container: TaggedElement | null,
  sTag: string | undefined,
): TaggedNode | null {
  if (!container || !sTag) return null;
  const childNodes = container.childNodes;
  for (let i = 0; i < childNodes.length; i++) {
    const node = childNodes[i] as TaggedNode;
    if (node.s_tag === sTag) return node;
  }
  return null;
}

/**
 * Move every sub-child of `child` to the start of `child_sibling`,
 * beginning from the last child, with word splitting and format
 * preservation. Typically `child` = the page that overflows,
 * `child_sibling` = the next page.
 */
export function moveChildrenForwardRecursively(
  child: TaggedElement,
  childSibling: TaggedElement,
  stopCondition: () => boolean,
  doNotBreak?: (el: HTMLElement) => boolean,
  notFirstChild?: boolean,
): void {
  while (child.childNodes.length && !stopCondition()) {
    notFirstChild = notFirstChild || child.childNodes.length !== 1;

    const subChild = child.lastChild as TaggedNode;
    if (!subChild) break;

    // Text node — split on WORD boundaries, move whole tokens from
    // the end of the source to the start of the continuation.
    //
    // This matches vue-document-editor's original behaviour and the
    // way Word / Google Docs lay out pagination: page breaks always
    // fall between words, never in the middle of one. Char-level
    // splitting (an earlier experiment) gives smoother boundary
    // movement on every keystroke but causes mid-word breaks visually
    // and lets the tighten pass insert chars into unexpected
    // positions, which looks like the page is "rearranging weirdly".
    if (subChild.nodeType === Node.TEXT_NODE) {
      const text = (subChild as Text).textContent ?? "";
      // Empty text node — remove and continue so the outer while loop
      // doesn't see the same node forever.
      if (text.length === 0) {
        child.removeChild(subChild);
        continue;
      }
      // /(\s|\S+)/g matches either a single whitespace char OR a run
      // of non-whitespace. Splitting on this preserves whitespace as
      // discrete tokens so the wrap point falls cleanly at a space.
      const tokens = text.match(/(\s|\S+)/g);
      const continuation = document.createTextNode("");
      childSibling.prepend(continuation);
      const l = tokens ? tokens.length : 0;
      for (let i = 0; i < l; i++) {
        // Preserve at least one token in the source if it's the only
        // child of its parent — otherwise the parent (its s_tag
        // shell) becomes empty and we'd remove it, breaking the
        // merge link for the next reflow.
        if (i === l - 1 && !notFirstChild) return;
        (subChild as Text).textContent = tokens!.slice(0, l - i - 1).join("");
        continuation.textContent = tokens!.slice(l - i - 1, l).join("");
        if (stopCondition()) return;
      }
      // All tokens moved — remove the now-empty source text node.
      if ((subChild as Text).textContent === "") {
        child.removeChild(subChild);
      }
      continue;
    }

    // Atomic / unsplittable elements — move whole.
    const subEl = subChild as TaggedElement;
    if (
      !subEl.childNodes.length ||
      /^h\d$/i.test(subEl.tagName) ||
      /^tr$/i.test(subEl.tagName) ||
      (typeof doNotBreak === "function" && doNotBreak(subEl))
    ) {
      if (!notFirstChild) {
        // last child remaining and still overflowing — bail.
        return;
      }
      childSibling.prepend(subEl);
      continue;
    }

    // Fast path — move the WHOLE container in ONE step when it will move
    // entirely anyway. The recurse below splits a container by moving its text
    // one token at a time, re-reading the page height after EACH word; for a
    // block that ends up moving wholly (the page is still over-full without
    // it) that is O(words) forced layouts for an O(1) outcome — the dominant
    // cost when paginating at scale. So tentatively move the whole block and
    // read the height ONCE: if the page is still over-full the block
    // legitimately belongs on the next page — the identical outcome to moving
    // all its words and dropping the emptied shell — so keep it and move on.
    // If it overshot, the block straddles the boundary: restore it and fall
    // through to the precise word-level split, which places the boundary
    // exactly as before. Pagination is byte-identical; only the read count
    // drops.
    //
    // Gated on notFirstChild for the same reason as the atomic branch: the
    // SOLE remaining block must be split in place (it may be taller than a
    // page), never shipped whole — that would empty the page.
    if (notFirstChild) {
      childSibling.prepend(subEl);
      if (!stopCondition()) {
        continue;
      }
      // Overshoot — straddles the boundary. Put it back (it was the last
      // child, so it returns to the end) and split it precisely below.
      child.appendChild(subEl);
    }

    // Container with children — clone shell to next page, recurse.
    let subChildSibling = findSubChildSiblingNode(
      childSibling,
      subEl.s_tag,
    ) as TaggedElement | null;
    if (!subChildSibling) {
      if (!subEl.s_tag) {
        subEl.s_tag = Math.random().toString(36).slice(2, 8);
      }
      subChildSibling = subEl.cloneNode(false) as TaggedElement;
      subChildSibling.s_tag = subEl.s_tag;
      childSibling.prepend(subChildSibling);
    }
    moveChildrenForwardRecursively(
      subEl,
      subChildSibling,
      stopCondition,
      doNotBreak,
      notFirstChild,
    );
    subChildSibling.normalize();

    if (child.contains(subEl)) {
      if (subEl.childNodes.length === 0 || subEl.innerHTML === "") {
        child.removeChild(subEl);
      }
    }
  }
}

function isMarker(node: Node | null): boolean {
  if (!node) return false;
  const name = (node as Element).nodeName?.toLowerCase?.() ?? "";
  return name === "pagedly-marker";
}

/**
 * Last child of `parent`, skipping any `<pagedly-marker>` cursor
 * preservation elements. Markers are transparent for boundary detection
 * — they were temporarily inserted by `fitContentOverPages` and don't
 * affect logical content.
 */
function lastChildSkippingMarkers(parent: Node): Node | null {
  let c: Node | null = parent.lastChild;
  while (c && isMarker(c)) c = c.previousSibling;
  return c;
}

function firstChildSkippingMarkers(parent: Node): Node | null {
  let c: Node | null = parent.firstChild;
  while (c && isMarker(c)) c = c.nextSibling;
  return c;
}

/**
 * Append `c` to the end of `block`. If the block's last child is a
 * text node, append to it. Otherwise (last child is a marker or other
 * element), create a new text node at the end. This keeps the
 * migrated char positioned at the visual end of the block regardless
 * of where the cursor markers are.
 */
function appendCharToBlockEnd(block: Element, c: string): void {
  const last = block.lastChild;
  if (last && last.nodeType === Node.TEXT_NODE) {
    (last as Text).textContent = ((last as Text).textContent ?? "") + c;
    return;
  }
  block.appendChild(document.createTextNode(c));
}

/**
 * Remove one char from the visual end of `block` and return it. Skips
 * marker elements. Returns null if no removable char exists.
 */
function popCharFromBlockEnd(block: Element): string | null {
  const last = lastChildSkippingMarkers(block);
  if (!last || last.nodeType !== Node.TEXT_NODE) return null;
  const t = last as Text;
  const txt = t.textContent ?? "";
  if (!txt.length) return null;
  const c = txt[txt.length - 1];
  t.textContent = txt.slice(0, -1);
  return c;
}

/**
 * Walk into pageDiv from its END and into nextPageDiv from its START,
 * descending matching s_tag chains (and skipping markers), until both
 * descend to a leaf text node on nextPageDiv's side. Returns the
 * source text on nextPageDiv plus the destination BLOCK on pageDiv
 * (the matching s_tag container whose end we should append to).
 */
function findBoundaryMigrationTarget(
  pageDiv: TaggedElement,
  nextPageDiv: TaggedElement,
): { sourceText: Text; destBlock: Element } | null {
  let pageNode: Node = pageDiv;
  let nextPageNode: Node = nextPageDiv;
  while (true) {
    const pageLast = lastChildSkippingMarkers(pageNode);
    const nextFirst = firstChildSkippingMarkers(nextPageNode);
    if (!pageLast || !nextFirst) return null;

    if (nextFirst.nodeType === Node.TEXT_NODE) {
      // Source side has hit text. Dest is the current pageNode (the
      // matching s_tag block on pageDiv) — we'll append the char to
      // its visual end.
      // pageLast can be text or marker-adjacent; either way, the
      // append helper handles it correctly.
      return {
        sourceText: nextFirst as Text,
        destBlock: pageNode as Element,
      };
    }
    if (pageLast.nodeType === Node.TEXT_NODE) {
      // pageDiv has hit text but nextPageDiv has an element — kinds
      // don't match. Can't migrate chars cleanly here.
      return null;
    }
    // Both elements — require matching s_tag to continue.
    const pageEl = pageLast as TaggedElement;
    const nextEl = nextFirst as TaggedElement;
    if (!pageEl.s_tag || pageEl.s_tag !== nextEl.s_tag) return null;
    pageNode = pageEl;
    nextPageNode = nextEl;
  }
}

/**
 * Post-pagination "tighten" pass: pull chars from start of next page
 * one at a time into the end of the current page, until the current
 * page is JUST at capacity (one more char would overflow).
 *
 * The main pagination pass uses clientHeight as its stop signal, but
 * clientHeight is quantised by line-wrap. Adding one char inside a
 * line doesn't change clientHeight; it only changes when a wrap point
 * moves. So after the main pass, the current page can have several
 * chars of slack — meaning a Backspace that deletes one char from
 * page N's bottom won't visibly migrate a char back from page N+1
 * (the algorithm sees no underflow).
 *
 * This pass closes that gap. After it runs, the boundary is at the
 * EXACT char position where the next char would overflow page N.
 */
export function tightenBoundaryCharByChar(
  pageDiv: TaggedElement,
  nextPageDiv: TaggedElement,
  targetHeight: number,
): void {
  const MAX_ITERS = 500;
  for (let n = 0; n < MAX_ITERS; n++) {
    if (pageDiv.clientHeight > targetHeight) return;
    const target = findBoundaryMigrationTarget(pageDiv, nextPageDiv);
    if (!target) return;
    const src = target.sourceText;
    if (!src.textContent || src.textContent.length === 0) return;

    const c = src.textContent[0];
    src.textContent = src.textContent.slice(1);
    appendCharToBlockEnd(target.destBlock, c);

    if (pageDiv.clientHeight > targetHeight) {
      // Overshot — pop that char back to source.
      const popped = popCharFromBlockEnd(target.destBlock);
      if (popped !== null) src.textContent = popped + (src.textContent ?? "");
      return;
    }
  }
}

/**
 * Force-migrate ONE WORD from the start of nextPageDiv back into the
 * end of pageDiv.
 *
 * A "word" here = optional leading whitespace + a non-whitespace run +
 * optional trailing whitespace. So e.g. "Hello world" → "Hello ".
 *
 * Returns the migrated word string if a migration happened (caller can
 * use this for an exact undo via `undoForceMigrate`), or null
 * otherwise.
 */
export function forceMigrateOneWordBackwards(
  pageDiv: TaggedElement,
  nextPageDiv: TaggedElement,
): string | null {
  const target = findBoundaryMigrationTarget(pageDiv, nextPageDiv);
  if (!target) return null;
  const src = target.sourceText;
  const text = src.textContent ?? "";
  if (!text.length) return null;
  const match = text.match(/^(\s*\S+\s*)/);
  if (!match) return null;
  const word = match[1];
  src.textContent = text.slice(word.length);
  appendCharToBlockEnd(target.destBlock, word);
  return word;
}

/**
 * Reverse a `forceMigrateOneWordBackwards`: remove the exact `word`
 * string from the end of pageDiv's matching boundary block and
 * prepend it back to nextPageDiv's matching first text. Used when the
 * force-migrate caused the page to overflow and we need to roll back.
 *
 * Operates on string equality — if the migrated content has been
 * altered since the migration (e.g. by subsequent normalize), bails
 * out rather than guessing.
 */
export function undoForceMigrate(
  pageDiv: TaggedElement,
  nextPageDiv: TaggedElement,
  word: string,
): boolean {
  const target = findBoundaryMigrationTarget(pageDiv, nextPageDiv);
  if (!target) return false;
  // The destBlock's last text node should END with `word`. Pop it.
  // Walk lastChild chain to find the trailing text node.
  let leaf: Node | null = target.destBlock;
  while (leaf && leaf.lastChild) leaf = leaf.lastChild;
  if (!leaf || leaf.nodeType !== Node.TEXT_NODE) return false;
  const t = leaf as Text;
  const txt = t.textContent ?? "";
  if (!txt.endsWith(word)) return false;
  t.textContent = txt.slice(0, txt.length - word.length);
  target.sourceText.textContent = word + (target.sourceText.textContent ?? "");
  return true;
}

/**
 * Move the first element of `nextPageDiv` back into `pageDiv`,
 * merging into a same-s_tag sibling if one exists (so split halves
 * rejoin transparently).
 */
export function moveChildrenBackwardsWithMerging(
  pageDiv: TaggedElement,
  nextPageDiv: TaggedElement,
  stopCondition: () => boolean,
): void {
  while (!stopCondition()) {
    const firstChild = nextPageDiv.firstChild as TaggedNode | null;
    if (!firstChild) break;

    const mergeRecursively = (container: TaggedElement, elt: TaggedNode): void => {
      const eltAsEl = elt as TaggedElement;
      const eltSibling = findSubChildSiblingNode(
        container,
        eltAsEl.s_tag,
      ) as TaggedElement | null;
      if (eltSibling && elt.childNodes.length) {
        mergeRecursively(eltSibling, elt.firstChild as TaggedNode);
      } else {
        container.append(elt);
        container.normalize();
      }
    };
    mergeRecursively(pageDiv, firstChild);
  }
}
