// Feature flags — every major editor feature is toggleable on/off by the
// host. A disabled feature is gated in TWO places: the Toolbar (button is not
// rendered) and Editor.runCommand (the command is a no-op). Pass a partial
// `features` object on EditorProps/LetterEditorProps; unspecified keys fall
// back to DEFAULT_FEATURES (everything on). Presets are exported for common
// shapes.

export interface EditorFeatures {
  // Inline marks
  bold?: boolean;
  italic?: boolean;
  underline?: boolean;
  strikethrough?: boolean;
  superscript?: boolean;
  subscript?: boolean;
  inlineCode?: boolean;
  // Inline style
  fontColor?: boolean;
  highlight?: boolean;
  fontFamily?: boolean;
  fontSize?: boolean;
  removeFormat?: boolean;
  // Blocks
  headings?: boolean;
  blockquote?: boolean;
  codeBlock?: boolean;
  alignment?: boolean;
  indent?: boolean;
  lineSpacing?: boolean;
  // Notes — TOGGLEABLE tri-state. "off" hides the button + no-ops the
  // command; "endnotes" collects notes at the document end (v1); "footnotes"
  // is reserved for true bottom-of-page placement and currently renders as
  // endnotes (see FOOTNOTES_DESIGN.md).
  footnotes?: "off" | "footnotes" | "endnotes";
  // Lists
  bulletList?: boolean;
  numberedList?: boolean;
  checklist?: boolean;
  // Insert
  link?: boolean;
  image?: boolean;
  table?: boolean;
  horizontalRule?: boolean;
  pageBreak?: boolean;
  // Find / output
  find?: boolean;
  print?: boolean;
  downloadPdf?: boolean;
  /** Export the document as a .docx download (toolbar/palette). */
  exportDocx?: boolean;
  /** Import a .docx file at the caret (toolbar/palette). */
  importDocx?: boolean;
  /** Copy/export the document as Markdown (toolbar/palette). */
  exportMarkdown?: boolean;
  /** Import a Markdown file at the caret (toolbar/palette). */
  importMarkdown?: boolean;
  // Paste controls (the "paste without formatting" + keep-formatting toggle)
  paste?: boolean;
  // UI chrome / productivity
  /** Live word / character / reading-time readout in the toolbar. */
  wordCount?: boolean;
  // Smart input
  /** Markdown autoformat on type (# →H1, - →bullet, **x** →bold, etc.). */
  markdownShortcuts?: boolean;
  /** Smart typography: -- →—, ... →…, (c)/(tm)/(r) → © ™ ®. */
  smartTypography?: boolean;
  /** Auto-link typed URLs on space. */
  autoLink?: boolean;
  /** Slash (/) command menu for inserting blocks/format at the caret. */
  slashMenu?: boolean;
  /** ⌘K / Ctrl-K command palette over the full action set. */
  commandPalette?: boolean;
  /** Document outline / navigation pane (heading tree, click to scroll). */
  outline?: boolean;
  /** Inline AI transform suite (only shown when an aiProvider is supplied). */
  ai?: boolean;
  /** Automatic hyphenation (hyphens:auto) for justified, dense text. */
  hyphenation?: boolean;
  /** On-screen widow/orphan control: keep short paragraphs whole (opt-in). */
  widowControl?: boolean;
  /** Inline comments (range-anchored highlights + host thread callbacks). */
  comments?: boolean;
  /** Track-changes review: accept/reject <ins>/<del> suggestion marks. */
  trackChanges?: boolean;
  /** Page-numbered table of contents (insert/refresh from headings). */
  toc?: boolean;
  /** Section breaks (new sheet in print) + per-section page-number restart. */
  sections?: boolean;
  /** Multi-column blocks (single-page; toggles column-count on the selection). */
  columns?: boolean;
  /** Leader rows (label · dotted leader · right-aligned value). */
  leaders?: boolean;
}

export type ResolvedFeatures = Required<EditorFeatures>;

