export const A4_PAGE_WIDTH_PX = Math.round(8.27 * 96);
export const A4_PAGE_HEIGHT_PX = Math.round(11.69 * 96);
export const A4_MARGIN_TOP_PX = Math.round(1.0 * 96);
export const A4_MARGIN_BOTTOM_PX = Math.round(1.2 * 96);
export const A4_MARGIN_SIDE_PX = Math.round(1.1 * 96);
export const A4_CONTENT_WIDTH_PX = A4_PAGE_WIDTH_PX - A4_MARGIN_SIDE_PX * 2;
export const A4_CONTENT_HEIGHT_PX = A4_PAGE_HEIGHT_PX - A4_MARGIN_TOP_PX - A4_MARGIN_BOTTOM_PX;

export type PageScaleOptions = {
  pageWidthPx?: number;
  minScale?: number;
  gutterPx?: number;
};

export function calculatePageScale(containerWidthPx: number, options: PageScaleOptions = {}): number {
  if (!Number.isFinite(containerWidthPx) || containerWidthPx <= 0) return 1;

  const pageWidthPx = options.pageWidthPx ?? A4_PAGE_WIDTH_PX;
  const minScale = options.minScale ?? 0.25;
  const gutterPx = options.gutterPx ?? 8;
  const available = Math.max(0, containerWidthPx - gutterPx);
  return Math.min(1, Math.max(minScale, available / pageWidthPx));
}

export function applyResponsivePageScale(container: HTMLElement | null, options: PageScaleOptions = {}): number {
  if (!container) return 1;
  const scale = calculatePageScale(container.getBoundingClientRect().width, options);
  container.style.setProperty("--pagedly-page-scale", formatScale(scale));
  return scale;
}

export function observeResponsivePageScale(
  container: HTMLElement,
  options: PageScaleOptions = {},
): () => void {
  let frame: number | null = null;
  const update = () => {
    frame = null;
    applyResponsivePageScale(container, options);
  };
  const schedule = () => {
    if (frame !== null) window.cancelAnimationFrame(frame);
    frame = window.requestAnimationFrame(update);
  };

  update();

  const resizeObserver =
    typeof ResizeObserver !== "undefined" ? new ResizeObserver(schedule) : null;
  resizeObserver?.observe(container);
  window.addEventListener("resize", schedule);
  window.visualViewport?.addEventListener("resize", schedule);

  return () => {
    if (frame !== null) window.cancelAnimationFrame(frame);
    resizeObserver?.disconnect();
    window.removeEventListener("resize", schedule);
    window.visualViewport?.removeEventListener("resize", schedule);
  };
}

function formatScale(scale: number): string {
  return Number(scale.toFixed(4)).toString();
}
