// True bottom-of-page footnotes. The note text travels ON the reference
// (data-fn-text) — there's no separate store block — and the per-page footnote
// AREA is stamped as inert chrome in the page's bottom margin (see the engine's
// stampPageChrome), regenerated after each reflow and stripped before reflow +
// serialize. So a footnote renders at the bottom of the page its reference lands
// on, with ZERO fit-loop contact: the pagination invariant is untouched.
//
// v1 places short footnotes in the existing bottom margin (no dynamic space
// reservation), which covers typical 1-3 line notes; reserving extra space for
// very long notes is a later fit-loop enhancement.

const REF_CLASS = "pagedly-fn-ref";

let counter = 0;
function newId(): string {
  counter += 1;
  return `fn-${Math.random().toString(36).slice(2, 8)}-${counter}`;
}

/**
 * Insert a footnote reference (carrying its note text) at the collapsed
 * selection. Returns the inserted <sup>, or null. Numbering is applied by the
 * engine's per-page footnote pass (document order).
 */
export function insertFootnoteAtSelection(
  content: HTMLElement,
  sel: Selection,
  noteText: string,
): HTMLElement | null {
  if (sel.rangeCount === 0) return null;
  const range = sel.getRangeAt(0);
  const ref = document.createElement("sup");
  ref.className = REF_CLASS;
  ref.setAttribute("data-fn", newId());
  ref.setAttribute("data-fn-text", noteText);
  ref.setAttribute("contenteditable", "false");
  ref.textContent = "0"; // the engine fills the real number
  range.deleteContents();
  range.insertNode(ref);
  return ref;
}

/**
 * Number every footnote reference in document order and build the per-page
 * footnote area for each page that carries refs WITH note text. Returns the
 * areas it created (already appended to their pages) so the engine can treat
 * them as inert chrome. Called from stampPageChrome (after reflow).
 */
export function stampFootnotes(
  content: HTMLElement,
  pages: HTMLElement[],
): void {
  const allRefs = Array.from(content.querySelectorAll<HTMLElement>(`sup.${REF_CLASS}`));
  if (allRefs.length === 0) return;
  // Doc-order numbering (covers endnote refs too — harmless, same order).
  allRefs.forEach((r, i) => {
    r.textContent = String(i + 1);
  });
  for (const page of pages) {
    const refs = Array.from(
      page.querySelectorAll<HTMLElement>(`sup.${REF_CLASS}[data-fn-text]`),
    );
    if (refs.length === 0) continue;
    const area = document.createElement("div");
    area.className = "pagedly-ce-footnotes";
    area.setAttribute("contenteditable", "false");
    area.setAttribute("aria-hidden", "true");
    for (const ref of refs) {
      const item = document.createElement("div");
      item.className = "pagedly-ce-footnotes__item";
      const num = document.createElement("sup");
      num.className = "pagedly-ce-footnotes__num";
      num.textContent = ref.textContent ?? "";
      item.appendChild(num);
      item.appendChild(document.createTextNode(" " + (ref.getAttribute("data-fn-text") ?? "")));
      area.appendChild(item);
    }
    page.appendChild(area);
  }
}

/** Whether the content has any true-footnote references. */
export function hasFootnotes(content: HTMLElement): boolean {
  return !!content.querySelector(`sup.${REF_CLASS}[data-fn-text]`);
}
