// Endnotes (toggleable via features.footnotes). v1 places notes in a single
// <ol class="pagedly-endnotes"> at the end of the document flow; each note's
// number comes from an inline <sup class="pagedly-fn-ref"> at the reference
// point. renumberEndnotes() keeps refs numbered in document order and the
// note list ordered + pruned to match — so it stays correct as refs are
// added/removed. NO fit-loop contact: the <ol> is ordinary measured content
// and the <sup> is an inline mark, so the pagination invariant is untouched.
//
// "footnotes" mode (true bottom-of-page placement) is reserved; for now it
// renders as endnotes too (see FOOTNOTES_DESIGN.md, Phase C).

const REF_CLASS = "pagedly-fn-ref";
const LIST_CLASS = "pagedly-endnotes";

let counter = 0;
function newId(): string {
  counter += 1;
  // App code (not a Workflow script) → Math.random is allowed; combine with a
  // counter so ids are unique within a session even on the same tick.
  return `fn-${Math.random().toString(36).slice(2, 8)}-${counter}`;
}

/** The endnotes <ol>, creating + appending it to the last page if missing. */
function ensureList(content: HTMLElement, sectionId: string | null): HTMLOListElement {
  let ol = content.querySelector<HTMLOListElement>(`ol.${LIST_CLASS}`);
  if (ol) return ol;
  ol = document.createElement("ol");
  ol.className = LIST_CLASS;
  if (sectionId) ol.setAttribute("data-section-id", sectionId);
  const pages = content.querySelectorAll<HTMLElement>(".pagedly-ce-page");
  const host = pages.length ? pages[pages.length - 1] : content;
  host.appendChild(ol);
  return ol;
}

/**
 * Insert a note reference at the collapsed selection + a matching note in the
 * endnotes list. Returns the new <li> so the caller can place the caret in it.
 */
export function insertEndnoteAtSelection(
  content: HTMLElement,
  sel: Selection,
): HTMLLIElement | null {
  if (sel.rangeCount === 0) return null;
  const range = sel.getRangeAt(0);
  const id = newId();

  // Inline reference at the caret.
  const ref = document.createElement("sup");
  ref.className = REF_CLASS;
  ref.setAttribute("data-fn", id);
  ref.setAttribute("contenteditable", "false");
  ref.textContent = "0"; // renumber fills the real value
  range.deleteContents();
  range.insertNode(ref);

  // Matching note. Inherit the section id of the ref's block so it round-trips
  // into the right letter section.
  let sectionId: string | null = null;
  let block: Node | null = ref.parentNode;
  while (block && block !== content) {
    if (block.nodeType === Node.ELEMENT_NODE) {
      const sid = (block as Element).getAttribute("data-section-id");
      if (sid) {
        sectionId = sid;
        break;
      }
    }
    block = block.parentNode;
  }
  const ol = ensureList(content, sectionId);
  const li = document.createElement("li");
  li.setAttribute("data-fn-note", id);
  li.appendChild(document.createElement("br"));
  ol.appendChild(li);

  renumberEndnotes(content);
  return li;
}

/**
 * Renumber every reference in document order and reorder + prune the note list
 * to match. Idempotent; safe to call on every settle. Removes an empty list.
 */
export function renumberEndnotes(content: HTMLElement): void {
  const ol = content.querySelector<HTMLOListElement>(`ol.${LIST_CLASS}`);
  const refs = Array.from(content.querySelectorAll<HTMLElement>(`sup.${REF_CLASS}`));

  if (!ol) return;

  if (refs.length === 0) {
    ol.remove();
    return;
  }

  // Number refs 1..N in document order.
  const orderedIds: string[] = [];
  refs.forEach((ref, i) => {
    ref.textContent = String(i + 1);
    const id = ref.getAttribute("data-fn");
    if (id) orderedIds.push(id);
  });

  // Reorder existing notes to match ref order; drop orphans (ref deleted).
  const notesById = new Map<string, HTMLLIElement>();
  for (const li of Array.from(ol.querySelectorAll<HTMLLIElement>("li[data-fn-note]"))) {
    const id = li.getAttribute("data-fn-note");
    if (id) notesById.set(id, li);
  }
  for (const [id, li] of notesById) {
    if (!orderedIds.includes(id)) li.remove();
  }
  for (const id of orderedIds) {
    const li = notesById.get(id);
    if (li) ol.appendChild(li); // appendChild re-inserts in order
  }
  if (ol.children.length === 0) ol.remove();
}
