// Page-numbered table of contents. Built from the document's headings; the page
// number for each entry is resolved AFTER layout (which .pagedly-ce-page the
// heading lands in). The numbers are written by these helpers — never during
// reflow — so the incremental==full invariant is unaffected.

/** All headings in the content, in document order, excluding the TOC itself. */
function documentHeadings(content: HTMLElement): HTMLElement[] {
  return Array.from(
    content.querySelectorAll<HTMLElement>("h1, h2, h3, h4, h5, h6"),
  ).filter((h) => !h.closest('[aria-hidden="true"]') && !h.closest(".pagedly-toc"));
}

/**
 * Resolve cross-references ("see p. N") to the laid-out page of their target
 * heading. Runs in the chrome pass after reflow so refs auto-update as content
 * shifts. The displayed text is content (serialized), set deterministically →
 * incremental==full unaffected (sig compares text distribution and both paths
 * resolve identically).
 */
export function resolveCrossRefs(content: HTMLElement): void {
  const xrefs = Array.from(content.querySelectorAll<HTMLElement>(".pagedly-xref"));
  if (xrefs.length === 0) return;
  const pages = Array.from(content.querySelectorAll<HTMLElement>(".pagedly-ce-page"));
  const headings = documentHeadings(content);
  const pageOf = (el: Element): number => {
    const page = el.closest(".pagedly-ce-page");
    const idx = page ? pages.indexOf(page as HTMLElement) : -1;
    return idx >= 0 ? idx + 1 : 0;
  };
  for (const x of xrefs) {
    // Resolve by the target heading's STABLE id first; fall back to the legacy
    // positional index only for xrefs authored before stable ids existed.
    const targetId = x.getAttribute("data-xref-target");
    let h: HTMLElement | null = targetId
      ? content.querySelector<HTMLElement>(`[data-xref-id="${targetId}"]`)
      : null;
    if (!h) {
      const i = Number(x.getAttribute("data-xref-index"));
      h = Number.isFinite(i) ? headings[i] ?? null : null;
    }
    const n = h ? pageOf(h) : 0;
    const next = n ? `p. ${n}` : "p. ?";
    if (x.textContent !== next) x.textContent = next;
  }
}

/** Build (or rebuild) the TOC element from the current headings. */
export function buildTocElement(content: HTMLElement): HTMLElement {
  const toc = document.createElement("div");
  toc.className = "pagedly-toc";
  toc.setAttribute("contenteditable", "false");
  const title = document.createElement("div");
  title.className = "pagedly-toc__title";
  title.textContent = "Contents";
  toc.appendChild(title);
  documentHeadings(content).forEach((h, i) => {
    const entry = document.createElement("div");
    entry.className = "pagedly-toc__entry";
    entry.setAttribute("data-toc-index", String(i));
    entry.setAttribute("data-toc-level", h.tagName[1]);
    const text = document.createElement("span");
    text.className = "pagedly-toc__text";
    text.textContent = (h.textContent ?? "").trim() || "(untitled)";
    const dots = document.createElement("span");
    dots.className = "pagedly-toc__dots";
    const num = document.createElement("span");
    num.className = "pagedly-toc__page";
    num.textContent = "";
    entry.appendChild(text);
    entry.appendChild(dots);
    entry.appendChild(num);
    toc.appendChild(entry);
  });
  return toc;
}

/**
 * Resolve each entry's page number from the laid-out DOM. Returns true if any
 * number changed (so the caller can decide whether another reflow pass is
 * worthwhile to reach a fixpoint).
 */
export function resolveTocPageNumbers(content: HTMLElement): boolean {
  const pages = Array.from(content.querySelectorAll<HTMLElement>(".pagedly-ce-page"));
  const pageIndex = (el: Element): number => {
    const page = el.closest(".pagedly-ce-page");
    const idx = page ? pages.indexOf(page as HTMLElement) : -1;
    return idx >= 0 ? idx + 1 : 0;
  };
  const headings = documentHeadings(content);
  let changed = false;
  for (const toc of Array.from(content.querySelectorAll<HTMLElement>(".pagedly-toc"))) {
    for (const entry of Array.from(toc.querySelectorAll<HTMLElement>(".pagedly-toc__entry"))) {
      const i = Number(entry.getAttribute("data-toc-index"));
      const h = headings[i];
      const num = entry.querySelector<HTMLElement>(".pagedly-toc__page");
      if (!h || !num) continue;
      const n = String(pageIndex(h) || "");
      if (num.textContent !== n) {
        num.textContent = n;
        changed = true;
      }
    }
  }
  return changed;
}
