// DOCX import — OOXML -> editor HTML. Boundary-only: the produced HTML flows
// through the normal insert path and the engine paginates it; this never touches
// the reflow. Dependency-free: a minimal ZIP reader (store + deflate via the
// platform DecompressionStream) + a focused WordprocessingML -> HTML mapping.

import { safeUrl } from "./sanitize";

// ── Minimal ZIP reader ────────────────────────────────────────────
async function inflateRaw(bytes: Uint8Array): Promise<Uint8Array> {
  // Platform DecompressionStream (Node 18+ / browsers). "deflate-raw" matches
  // the raw DEFLATE stream stored in a ZIP entry.
  const DS = (globalThis as unknown as { DecompressionStream?: typeof DecompressionStream }).DecompressionStream;
  if (!DS) throw new Error("DecompressionStream unavailable; cannot inflate DOCX");
  const ds = new DS("deflate-raw");
  const stream = new Response(bytes as unknown as BodyInit).body!.pipeThrough(ds);
  const ab = await new Response(stream).arrayBuffer();
  return new Uint8Array(ab);
}

/** Read a single entry's bytes (store or deflate) from a ZIP by name. */
async function readZipEntry(zip: Uint8Array, name: string): Promise<Uint8Array | null> {
  const dv = new DataView(zip.buffer, zip.byteOffset, zip.byteLength);
  // Locate the End Of Central Directory record (scan back for 0x06054b50). The
  // signature can also appear by chance inside an archive comment or entry data,
  // so validate the EOCD comment-length field points exactly at the end of the
  // buffer before accepting the candidate.
  let eocd = -1;
  for (let i = zip.length - 22; i >= 0; i--) {
    if (dv.getUint32(i, true) !== 0x06054b50) continue;
    const commentLen = dv.getUint16(i + 20, true);
    if (i + 22 + commentLen === zip.length) { eocd = i; break; }
  }
  if (eocd < 0) return null;
  const count = dv.getUint16(eocd + 10, true);
  let off = dv.getUint32(eocd + 16, true);
  const dec = new TextDecoder();
  for (let n = 0; n < count; n++) {
    if (dv.getUint32(off, true) !== 0x02014b50) break;
    const method = dv.getUint16(off + 10, true);
    const compSize = dv.getUint32(off + 20, true);
    const nameLen = dv.getUint16(off + 28, true);
    const extraLen = dv.getUint16(off + 30, true);
    const commentLen = dv.getUint16(off + 32, true);
    const localOff = dv.getUint32(off + 42, true);
    const entryName = dec.decode(zip.subarray(off + 46, off + 46 + nameLen));
    if (entryName === name) {
      // Read the local header to find where the data starts.
      const lNameLen = dv.getUint16(localOff + 26, true);
      const lExtraLen = dv.getUint16(localOff + 28, true);
      const dataStart = localOff + 30 + lNameLen + lExtraLen;
      const data = zip.subarray(dataStart, dataStart + compSize);
      if (method === 0) return data.slice();
      if (method === 8) return inflateRaw(data);
      return null; // unsupported method
    }
    off += 46 + nameLen + extraLen + commentLen;
  }
  return null;
}

// ── WordprocessingML -> HTML ──────────────────────────────────────
const W = "http://schemas.openxmlformats.org/wordprocessingml/2006/main";
// DrawingML (a:blip lives here), the OOXML relationship-attribute namespace
// (r:embed), the WordprocessingDrawing wrapper (wp:extent), and the package
// relationships part schema (word/_rels/document.xml.rels).
const A = "http://schemas.openxmlformats.org/drawingml/2006/main";
const R = "http://schemas.openxmlformats.org/officeDocument/2006/relationships";
const WP = "http://schemas.openxmlformats.org/drawingml/2006/wordprocessingDrawing";
const RELS = "http://schemas.openxmlformats.org/package/2006/relationships";
const wq = (el: Element, tag: string): Element | null => el.getElementsByTagNameNS(W, tag)[0] ?? null;
const wVal = (el: Element | null): string | null => (el ? el.getAttributeNS(W, "val") ?? el.getAttribute("w:val") : null);

const escapeHtml = (s: string): string =>
  s.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;");

/** Direct-child elements by local name (avoids descending into nested tables). */
function childrenByLocal(el: Element, local: string): Element[] {
  return Array.from(el.children).filter((c) => c.localName === local);
}

// A valid 3/6-digit hex color (Word also emits "auto" — skip that).
const isHexColor = (v: string | null): v is string => !!v && /^[0-9a-fA-F]{3,6}$/.test(v);

// Build the inline-style string for a run's visual character formatting that has
// no semantic tag: font-size (w:sz is half-points), text color, highlight
// background, and a custom font family. Bold/italic/underline/strike stay
// semantic (<strong>/<em>/<u>/<s>) so they round-trip through Markdown/DOCX.
function runStyle(rPr: Element): string {
  const decls: string[] = [];
  const sz = wVal(wq(rPr, "sz")); // half-points
  if (sz && /^\d+$/.test(sz)) {
    const pt = Number(sz) / 2;
    if (pt > 0 && pt < 400) decls.push(`font-size:${pt}pt`);
  }
  const color = wVal(wq(rPr, "color"));
  if (isHexColor(color)) decls.push(`color:#${color.length === 3 ? color : color.padStart(6, "0")}`);
  const hl = wq(rPr, "highlight"); // named color, e.g. "yellow"
  const hlVal = wVal(hl);
  if (hlVal && hlVal !== "none" && /^[a-zA-Z]+$/.test(hlVal)) decls.push(`background-color:${hlVal}`);
  const shd = wq(rPr, "shd"); // shading fill = highlight via hex
  const shdFill = shd ? shd.getAttributeNS(W, "fill") ?? shd.getAttribute("w:fill") : null;
  if (isHexColor(shdFill)) decls.push(`background-color:#${shdFill}`);
  const fonts = wq(rPr, "rFonts");
  const face = fonts ? fonts.getAttributeNS(W, "ascii") ?? fonts.getAttribute("w:ascii") : null;
  if (face && /^[\w \-]+$/.test(face)) decls.push(`font-family:'${face}'`);
  return decls.join(";");
}

// ── Inline images (w:drawing → data-URL <img>) ───────────────────
// rId → data:image/...;base64 URL, pre-extracted ONCE in docxToHtml (the run/
// paragraph mappers are sync; the only async work — reading + inflating the
// media entries — happens up front).
type ImageMap = Map<string, string>;
const EMPTY_IMAGES: ImageMap = new Map();

// rId → external hyperlink target (word/_rels/document.xml.rels, Type ending
// "/hyperlink", TargetMode="External"). Pre-extracted once like the image map.
type LinkMap = Map<string, string>;
const EMPTY_LINKS: LinkMap = new Map();

/**
 * Read + parse word/_rels/document.xml.rels ONCE; both the image and the
 * hyperlink maps are derived from the returned Relationship elements. Returns
 * [] when the part is absent/unreadable (each consumer then resolves nothing).
 */
async function readRelationships(bytes: Uint8Array): Promise<Element[]> {
  const relsXml = await readZipEntry(bytes, "word/_rels/document.xml.rels");
  if (!relsXml) return [];
  const relsDoc = new DOMParser().parseFromString(new TextDecoder().decode(relsXml), "application/xml");
  const rels = relsDoc.getElementsByTagNameNS(RELS, "Relationship");
  return rels.length ? Array.from(rels) : Array.from(relsDoc.getElementsByTagName("Relationship"));
}

/** rId → raw external target for hyperlink relationships. URL safety is the
 * consumer's job (safeUrl at emit time) — a javascript: target resolves here
 * but renders as plain flattened text. */
function hyperlinkTargets(rels: Element[]): LinkMap {
  const map: LinkMap = new Map();
  for (const rel of rels) {
    const id = rel.getAttribute("Id");
    const type = rel.getAttribute("Type") ?? "";
    const target = rel.getAttribute("Target") ?? "";
    const mode = rel.getAttribute("TargetMode") ?? "";
    if (id && target && type.endsWith("/hyperlink") && mode === "External") map.set(id, target);
  }
  return map;
}

// Base64 WITHOUT btoa-on-a-huge-binary-string (stack/arg limits, latin1
// round-trip pitfalls): a manual 3-bytes→4-chars table encoder. Works the same
// in jsdom and browsers; O(n), no intermediate string of the raw bytes.
const B64_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
function bytesToBase64(bytes: Uint8Array): string {
  const out: string[] = [];
  let i = 0;
  for (; i + 2 < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8) | bytes[i + 2];
    out.push(
      B64_ALPHABET[(n >> 18) & 63] + B64_ALPHABET[(n >> 12) & 63] +
      B64_ALPHABET[(n >> 6) & 63] + B64_ALPHABET[n & 63],
    );
  }
  const rest = bytes.length - i;
  if (rest === 1) {
    const n = bytes[i] << 16;
    out.push(B64_ALPHABET[(n >> 18) & 63] + B64_ALPHABET[(n >> 12) & 63] + "==");
  } else if (rest === 2) {
    const n = (bytes[i] << 16) | (bytes[i + 1] << 8);
    out.push(B64_ALPHABET[(n >> 18) & 63] + B64_ALPHABET[(n >> 12) & 63] + B64_ALPHABET[(n >> 6) & 63] + "=");
  }
  return out.join("");
}

// MIME by media-file extension. svg/emf/wmf are deliberately ABSENT — svg can
// script and emf/wmf aren't browser formats — those drawings get dropped.
const IMAGE_MIME: Record<string, string> = {
  png: "image/png",
  jpg: "image/jpeg",
  jpeg: "image/jpeg",
  gif: "image/gif",
  webp: "image/webp",
};
const SKIPPED_IMAGE_EXT = new Set(["svg", "emf", "wmf"]);

// Relationship targets are relative to word/ ("media/image1.png",
// "../media/image1.png") or package-absolute ("/word/media/image1.png").
// Normalize to the ZIP entry name (no leading slash, ".." collapsed).
function resolveMediaPath(target: string): string {
  const t = target.trim();
  const joined = t.startsWith("/") ? t : `word/${t}`;
  const out: string[] = [];
  for (const part of joined.split("/")) {
    if (!part || part === ".") continue;
    if (part === "..") out.pop();
    else out.push(part);
  }
  return out.join("/");
}

/**
 * Build the rId → data-URL map for every image relationship the document
 * actually references (a:blip r:embed). Unknown extensions fall back to
 * image/png; svg/emf/wmf and unreadable/missing media are skipped — their
 * drawings render as nothing rather than a broken <img>.
 */
async function extractImageDataUrls(bytes: Uint8Array, doc: Document, rels: Element[]): Promise<ImageMap> {
  const map: ImageMap = new Map();
  const used = new Set<string>();
  for (const blip of Array.from(doc.getElementsByTagNameNS(A, "blip"))) {
    const rid = blip.getAttributeNS(R, "embed") ?? blip.getAttribute("r:embed");
    if (rid) used.add(rid);
  }
  if (!used.size) return map;
  for (const rel of rels) {
    const id = rel.getAttribute("Id");
    const type = rel.getAttribute("Type") ?? "";
    const target = rel.getAttribute("Target") ?? "";
    if (!id || !target || !used.has(id) || !type.endsWith("/image")) continue;
    const ext = (/\.([A-Za-z0-9]+)$/.exec(target)?.[1] ?? "").toLowerCase();
    if (SKIPPED_IMAGE_EXT.has(ext)) continue;
    const mime = IMAGE_MIME[ext] ?? "image/png";
    try {
      const media = await readZipEntry(bytes, resolveMediaPath(target));
      if (!media || !media.length) continue;
      map.set(id, `data:${mime};base64,${bytesToBase64(media)}`);
    } catch {
      // A corrupt media entry drops ITS drawing, not the whole import.
    }
  }
  return map;
}

// Max rendered width: wider drawings are scaled down proportionally (the
// max-width:100% style additionally caps them to the live column).
const MAX_IMG_PX = 700;
const EMU_PER_PX = 9525;

function drawingToHtml(drawing: Element, images: ImageMap): string {
  const blip = drawing.getElementsByTagNameNS(A, "blip")[0];
  if (!blip) return "";
  const rid = blip.getAttributeNS(R, "embed") ?? blip.getAttribute("r:embed");
  const dataUrl = rid ? images.get(rid) : undefined;
  if (!dataUrl) return ""; // unresolved / skipped format → drop silently
  // The data URL is self-generated, but run it through safeUrl anyway so every
  // string-templated src in the codebase goes through the same validator.
  const src = safeUrl(dataUrl);
  if (!src) return "";
  let sizeAttrs = "";
  const extent = drawing.getElementsByTagNameNS(WP, "extent")[0];
  const cx = extent?.getAttribute("cx");
  const cy = extent?.getAttribute("cy");
  if (cx && cy && /^\d+$/.test(cx) && /^\d+$/.test(cy)) {
    let w = Math.round(Number(cx) / EMU_PER_PX);
    let h = Math.round(Number(cy) / EMU_PER_PX);
    if (w > 0 && h > 0) {
      if (w > MAX_IMG_PX) {
        h = Math.max(1, Math.round((h * MAX_IMG_PX) / w));
        w = MAX_IMG_PX;
      }
      sizeAttrs = ` width="${w}" height="${h}"`;
    }
  }
  return `<img src="${src}"${sizeAttrs} style="max-width:100%;height:auto;">`;
}

// <w:tab/> = jump to the next tab stop. Faithful tab stops are out of scope —
// an em space reads naturally, needs zero sanitizer support (the letter style
// normalizer would strip a display:inline-block/width spacer span), and
// survives every save/copy path as plain text.
const TAB_SPACER = "\u2003"; // EM SPACE

function runToHtml(r: Element, images: ImageMap): string {
  const rPr = wq(r, "rPr");
  // Iterate the run's children IN ORDER so text-tab-text / text-br-text
  // sequencing is preserved (the old wAll(t)+wAll(br) approach lost interior
  // breaks and had no tab support at all).
  const parts: string[] = [];
  let hasText = false;
  for (const child of Array.from(r.children)) {
    switch (child.localName) {
      case "t": {
        const t = child.textContent ?? "";
        if (t) { parts.push(escapeHtml(t)); hasText = true; }
        break;
      }
      case "br": parts.push("<br>"); break;
      case "tab": parts.push(TAB_SPACER); hasText = true; break;
      case "drawing": parts.push(drawingToHtml(child, images)); break;
    }
  }
  let html = parts.join("");
  if (!html) return "";
  if (rPr && hasText) {
    // Visual styling (size/color/highlight/font) wraps closest to the text.
    const style = runStyle(rPr);
    if (style) html = `<span style="${style}">${html}</span>`;
    if (wq(rPr, "b")) html = `<strong>${html}</strong>`;
    if (wq(rPr, "i")) html = `<em>${html}</em>`;
    if (wq(rPr, "u")) html = `<u>${html}</u>`;
    if (wq(rPr, "strike")) html = `<s>${html}</s>`;
  }
  return html;
}

function paragraphInner(p: Element, images: ImageMap, links: LinkMap = EMPTY_LINKS): string {
  // Inline images live in runs (w:drawing); links live in hyperlink wrappers —
  // r:id resolves through the rels-derived LinkMap (external targets), w:anchor
  // becomes a fragment href. An unresolvable or unsafe target keeps the
  // flattened text (no dead/dangerous link).
  const parts: string[] = [];
  for (const child of Array.from(p.children)) {
    if (child.localName === "r") parts.push(runToHtml(child, images));
    else if (child.localName === "hyperlink") {
      const inner = childrenByLocal(child, "r").map((r) => runToHtml(r, images)).join("");
      const rid = child.getAttributeNS(R, "id") ?? child.getAttribute("r:id");
      const anchor = child.getAttributeNS(W, "anchor") ?? child.getAttribute("w:anchor");
      const target = rid ? links.get(rid) : undefined;
      // safeUrl rejects javascript:/vbscript:/data:text etc. (returns "") and
      // escapes attribute-breaking characters in what it accepts.
      const href = target ? safeUrl(target) : anchor ? safeUrl(`#${anchor}`) : "";
      parts.push(href && inner ? `<a href="${href}">${inner}</a>` : inner);
    }
  }
  const inner = parts.join("");
  return inner || "<br>";
}

// Paragraph-level visual style: alignment (w:jc) → text-align, plus the
// paragraph's OWN spacing (w:spacing before/after in twips, line in 240ths) →
// margin-top/bottom + line-height. Honoring the source spacing is what makes the
// imported page count match the original — otherwise every paragraph inherits the
// editor's 12pt space-after + 1.15 line-height and the document grows by a page+.
// Document-default metrics (from styles.xml docDefaults) — the fallback when a
// paragraph doesn't set its own. Honoring these is what makes the imported page
// count match the source instead of inheriting the editor's looser defaults.
// OOXML hard defaults when nothing specifies them: w:sz = 20 half-points (10pt),
// single line spacing (1.0). The editor's own base (11pt / 1.15) is LOOSER, so
// imported content rendered taller than the source (an extra page). Using the
// document/OOXML defaults for unsized/unspaced runs keeps the page count faithful.
const OOXML_DEFAULT_FONT_PT = 10;
const OOXML_SINGLE_LINE = 1.0;
type DocDefaults = { after?: number; before?: number; lineHeight?: number; fontPt?: number };

function spacingFromEl(sp: Element | null): { after?: number; before?: number; lineHeight?: number } {
  if (!sp) return {};
  const attr = (n: string) => sp.getAttributeNS(W, n) ?? sp.getAttribute(`w:${n}`);
  const out: { after?: number; before?: number; lineHeight?: number } = {};
  const after = attr("after");
  const before = attr("before");
  const line = attr("line");
  const lineRule = attr("lineRule");
  if (after != null && /^\d+$/.test(after)) out.after = Number(after) / 20; // twips → pt
  if (before != null && /^\d+$/.test(before)) out.before = Number(before) / 20;
  if (line && /^\d+$/.test(line) && (!lineRule || lineRule === "auto")) {
    const lh = Number(line) / 240;
    if (lh > 0.5 && lh < 4) out.lineHeight = lh;
  } else if (!lineRule || lineRule === "auto") {
    // A spacing element with auto rule but no explicit line = single (OOXML
    // default). Emitting it overrides the editor's looser 1.15 for this para.
    out.lineHeight = OOXML_SINGLE_LINE;
  }
  return out;
}

// The default paragraph style's (or docDefaults') sz, in pt. Falls through
// docDefaults rPr → the w:default paragraph style (usually "Normal") → OOXML 10pt.
function readDefaultFontPt(doc: Document): number {
  const dd = doc.getElementsByTagNameNS(W, "docDefaults")[0];
  const ddSz = dd ? wVal(wq(dd, "sz")) : null;
  if (ddSz && /^\d+$/.test(ddSz)) return Number(ddSz) / 2;
  for (const st of Array.from(doc.getElementsByTagNameNS(W, "style"))) {
    const isDefaultPara =
      (st.getAttributeNS(W, "type") ?? st.getAttribute("w:type")) === "paragraph" &&
      ((st.getAttributeNS(W, "default") ?? st.getAttribute("w:default")) === "1");
    if (isDefaultPara) {
      const sz = wVal(wq(st, "sz"));
      if (sz && /^\d+$/.test(sz)) return Number(sz) / 2;
    }
  }
  return OOXML_DEFAULT_FONT_PT;
}

function readDocDefaults(doc: Document): DocDefaults {
  const dd = doc.getElementsByTagNameNS(W, "docDefaults")[0];
  const pPr = dd
    ? dd.getElementsByTagNameNS(W, "pPrDefault")[0]?.getElementsByTagNameNS(W, "pPr")[0] ?? null
    : null;
  return { ...spacingFromEl(pPr ? wq(pPr, "spacing") : null), fontPt: readDefaultFontPt(doc) };
}

// The document's default font family: docDefaults rPr w:rFonts ascii, falling
// back to the w:default paragraph style's. Validated like runStyle (word chars,
// spaces, hyphens only) so it is safe to interpolate into a CSS value.
function readDefaultFontFamily(doc: Document): string | undefined {
  const faceOf = (scope: Element | null): string | null => {
    const fonts = scope ? wq(scope, "rFonts") : null;
    return fonts ? fonts.getAttributeNS(W, "ascii") ?? fonts.getAttribute("w:ascii") : null;
  };
  const dd = doc.getElementsByTagNameNS(W, "docDefaults")[0] ?? null;
  let face = faceOf(dd);
  if (!face) {
    for (const st of Array.from(doc.getElementsByTagNameNS(W, "style"))) {
      const isDefaultPara =
        (st.getAttributeNS(W, "type") ?? st.getAttribute("w:type")) === "paragraph" &&
        (st.getAttributeNS(W, "default") ?? st.getAttribute("w:default")) === "1";
      if (isDefaultPara) {
        face = faceOf(st);
        break;
      }
    }
  }
  return face && /^[\w \-]+$/.test(face) ? face : undefined;
}

// ── Document-style baseline (typing defaults) ─────────────────────
export type DocxDocumentDefaults = {
  fontPt?: number;
  lineHeight?: number;
  fontFamily?: string;
};

/**
 * The imported document's default text metrics (styles.xml docDefaults +
 * default paragraph style): font size, line height, font family. The host
 * applies these as the editor's typing baseline (--pagedly-font-size /
 * --pagedly-line-height / --pagedly-font-family) so text TYPED after an
 * import matches the imported document's look instead of the editor's house
 * style. Returns null when styles.xml is absent/unreadable so callers keep
 * the configured baseline. fontPt is always present when non-null (it falls
 * through to the OOXML 10pt hard default — the same value paragraphToHtml
 * already renders body blocks with, so typing stays consistent with the
 * imported content either way).
 */
export async function docxDocumentDefaults(bytes: Uint8Array): Promise<DocxDocumentDefaults | null> {
  try {
    const stylesXml = await readZipEntry(bytes, "word/styles.xml");
    if (!stylesXml) return null;
    const doc = new DOMParser().parseFromString(new TextDecoder().decode(stylesXml), "application/xml");
    const d = readDocDefaults(doc);
    const out: DocxDocumentDefaults = { fontPt: d.fontPt };
    if (d.lineHeight != null) out.lineHeight = d.lineHeight;
    const fontFamily = readDefaultFontFamily(doc);
    if (fontFamily) out.fontFamily = fontFamily;
    return out;
  } catch {
    return null;
  }
}

// Indentation (w:ind, attributes in twips, 20/pt). left|start → margin-left,
// right|end → margin-right, firstLine → text-indent, hanging → negative
// text-indent PLUS the hanging amount added to margin-left (Word semantics:
// hanging indents the paragraph body while the first line stays put). Each
// value is clamped to ±4in (288pt) so a corrupt file can't blow up the layout.
const MAX_INDENT_PT = 288; // 4in
function indentStyle(pPr: Element | null): string[] {
  const ind = pPr ? wq(pPr, "ind") : null;
  if (!ind) return [];
  const pt = (n: string): number | null => {
    const v = ind.getAttributeNS(W, n) ?? ind.getAttribute(`w:${n}`);
    return v != null && /^-?\d+$/.test(v) ? Number(v) / 20 : null; // twips → pt
  };
  const clamp = (v: number) => Math.max(-MAX_INDENT_PT, Math.min(MAX_INDENT_PT, v));
  const fmt = (v: number) => `${Math.round(clamp(v) * 100) / 100}pt`;
  const decls: string[] = [];
  let left = pt("left") ?? pt("start");
  const right = pt("right") ?? pt("end");
  const hanging = pt("hanging");
  const firstLine = pt("firstLine");
  if (hanging != null && hanging > 0) {
    decls.push(`text-indent:${fmt(-hanging)}`);
    left = (left ?? 0) + hanging;
  } else if (firstLine != null && firstLine > 0) {
    decls.push(`text-indent:${fmt(firstLine)}`);
  }
  if (left != null && left !== 0) decls.push(`margin-left:${fmt(left)}`);
  if (right != null && right !== 0) decls.push(`margin-right:${fmt(right)}`);
  return decls;
}

function paragraphStyle(pPr: Element | null, defaults: DocDefaults): string {
  const decls: string[] = [];
  const jc = pPr ? wVal(wq(pPr, "jc")) : null;
  const map: Record<string, string> = { center: "center", right: "right", both: "justify", end: "right" };
  if (jc && map[jc]) decls.push(`text-align:${map[jc]}`);
  decls.push(...indentStyle(pPr));
  // Paragraph's own spacing, else the document default — always emit explicit
  // values so imported paragraphs don't pick up the editor's 12pt / 1.15.
  const own = spacingFromEl(pPr ? wq(pPr, "spacing") : null);
  const after = own.after ?? defaults.after;
  const before = own.before ?? defaults.before;
  const lineHeight = own.lineHeight ?? defaults.lineHeight;
  if (after != null) decls.push(`margin-bottom:${Math.min(after, 72).toFixed(1)}pt`);
  if (before != null) decls.push(`margin-top:${Math.min(before, 72).toFixed(1)}pt`);
  if (lineHeight != null) decls.push(`line-height:${lineHeight.toFixed(3)}`);
  return decls.join(";");
}

// ── Real list numbering (word/numbering.xml) ─────────────────────
// numId → (ilvl → numFmt). A paragraph's numPr names a numId; the num maps to
// an abstractNum whose w:lvl entries carry the per-level w:numFmt ("bullet",
// "decimal", "lowerLetter", …). "bullet" → <ul>, anything else → <ol>.
type NumberingMap = Map<string, Map<number, string>>;
const EMPTY_NUMBERING: NumberingMap = new Map();

async function readNumbering(bytes: Uint8Array): Promise<NumberingMap> {
  const map: NumberingMap = new Map();
  try {
    const xml = await readZipEntry(bytes, "word/numbering.xml");
    if (!xml) return map;
    const doc = new DOMParser().parseFromString(new TextDecoder().decode(xml), "application/xml");
    const attr = (el: Element, n: string) => el.getAttributeNS(W, n) ?? el.getAttribute(`w:${n}`);
    // abstractNumId → (ilvl → numFmt)
    const abstracts = new Map<string, Map<number, string>>();
    for (const an of Array.from(doc.getElementsByTagNameNS(W, "abstractNum"))) {
      const id = attr(an, "abstractNumId");
      if (id == null) continue;
      const levels = new Map<number, string>();
      for (const lvl of childrenByLocal(an, "lvl")) {
        const ilvl = attr(lvl, "ilvl");
        const fmt = wVal(wq(lvl, "numFmt"));
        if (ilvl != null && /^\d+$/.test(ilvl) && fmt) levels.set(Number(ilvl), fmt);
      }
      abstracts.set(id, levels);
    }
    for (const num of Array.from(doc.getElementsByTagNameNS(W, "num"))) {
      const numId = attr(num, "numId");
      const abstractId = wVal(wq(num, "abstractNumId"));
      if (numId == null || abstractId == null) continue;
      const levels = abstracts.get(abstractId);
      if (levels) map.set(numId, levels);
    }
  } catch {
    // Malformed numbering.xml degrades to the legacy numId heuristic.
  }
  return map;
}

function paragraphToHtml(
  p: Element,
  defaults: DocDefaults,
  images: ImageMap = EMPTY_IMAGES,
  links: LinkMap = EMPTY_LINKS,
  numbering: NumberingMap = EMPTY_NUMBERING,
): string {
  const pPr = wq(p, "pPr");
  const style = wVal(pPr ? wq(pPr, "pStyle") : null) ?? "";
  const inner = paragraphInner(p, images, links);
  const styleAttr = paragraphStyle(pPr, defaults);
  const sa = styleAttr ? ` style="${styleAttr}"` : "";
  // Body blocks carry the document's default font size so UNSIZED runs match the
  // source (≈10pt) instead of the editor's 11pt base; sized run <span>s override.
  // Headings keep their own scale (they get the big sized runs anyway).
  const bodyFont = defaults.fontPt ? `font-size:${defaults.fontPt}pt` : "";
  const bsa = (extra: string) => {
    const s = [bodyFont, extra].filter(Boolean).join(";");
    return s ? ` style="${s}"` : "";
  };
  const heading = /^Heading([1-6])$/.exec(style);
  if (heading) return `<h${heading[1]}${sa}>${inner}</h${heading[1]}>`;
  if (/^(Title|Subtitle)$/i.test(style)) return `<h1${sa}>${inner}</h1>`;
  if (/^Quote$/i.test(style)) return `<blockquote${bsa(styleAttr)}>${inner}</blockquote>`;
  // List item?
  const numPr = pPr ? wq(pPr, "numPr") : null;
  if (numPr) {
    const numId = wVal(wq(numPr, "numId"));
    const ilvlRaw = wVal(wq(numPr, "ilvl"));
    const ilvl = ilvlRaw != null && /^\d+$/.test(ilvlRaw) ? Math.min(Number(ilvlRaw), 8) : 0;
    // Real numbering.xml resolution: numId → abstractNum → this level's numFmt.
    // "bullet" → ul; decimal/lowerLetter/roman/… → ol. When numbering.xml is
    // absent (or the numId/level is undefined there), fall back to the legacy
    // heuristic: numId 2 == decimal in our exporter, everything else bullet.
    const fmt = numId ? numbering.get(numId)?.get(ilvl) ?? numbering.get(numId)?.get(0) : undefined;
    const tag = fmt ? (fmt === "bullet" ? "ul" : "ol") : numId === "2" ? "ol" : "ul";
    // data-ilvl is transient — coalesceLists consumes it for nesting and strips it.
    return `<li data-list="${tag}" data-ilvl="${ilvl}"${bsa(styleAttr)}>${inner}</li>`;
  }
  return `<p${bsa(styleAttr)}>${inner}</p>`;
}

function tableToHtml(tbl: Element, images: ImageMap = EMPTY_IMAGES, links: LinkMap = EMPTY_LINKS): string {
  const rows = childrenByLocal(tbl, "tr")
    .map((tr) => {
      const cells = childrenByLocal(tr, "tc")
        .map((tc) => `<td>${childrenByLocal(tc, "p").map((p) => paragraphInner(p, images, links)).join("<br>")}</td>`)
        .join("");
      return `<tr>${cells}</tr>`;
    })
    .join("");
  return `<table class="pagedly-table"><tbody>${rows}</tbody></table>`;
}

/**
 * Wrap consecutive <li data-list data-ilvl> siblings into <ul>/<ol>, NESTING by
 * ilvl: a deeper level opens a nested list inside the previous <li>; a
 * shallower level closes back down. ilvl-0-only documents produce exactly the
 * old flat output. The transient data-list/data-ilvl markers are stripped.
 */
function coalesceLists(blocks: string[]): string {
  const out: string[] = [];
  type Level = { tag: string; ilvl: number; items: string[] };
  const stack: Level[] = [];
  const closeTop = () => {
    const top = stack.pop()!;
    const html = `<${top.tag}>${top.items.join("")}</${top.tag}>`;
    const parent = stack[stack.length - 1];
    if (!parent) { out.push(html); return; }
    if (parent.items.length) {
      // Nest INSIDE the previous item (before its </li>) — the HTML-valid shape.
      parent.items[parent.items.length - 1] =
        parent.items[parent.items.length - 1].replace(/<\/li>$/, `${html}</li>`);
    } else {
      // A list that STARTS at a deep level (no preceding shallower item) gets a
      // host <li> so the markup stays valid.
      parent.items.push(`<li>${html}</li>`);
    }
  };
  const closeAll = () => { while (stack.length) closeTop(); };
  for (const b of blocks) {
    // Tolerate extra attributes on the <li> (e.g. style="…" carried from import).
    const m = /^<li data-list="(ul|ol)"(?: data-ilvl="(\d+)")?([^>]*)>([\s\S]*)<\/li>$/.exec(b);
    if (!m) { closeAll(); out.push(b); continue; }
    const tag = m[1];
    const ilvl = m[2] != null ? Number(m[2]) : 0;
    const attrs = m[3];
    // Shallower item → close deeper lists (each folds into its parent's last <li>).
    while (stack.length && stack[stack.length - 1].ilvl > ilvl) closeTop();
    // Same level, different list type → close that list, start a sibling one.
    if (stack.length && stack[stack.length - 1].ilvl === ilvl && stack[stack.length - 1].tag !== tag) closeTop();
    if (!stack.length || stack[stack.length - 1].ilvl < ilvl) stack.push({ tag, ilvl, items: [] });
    stack[stack.length - 1].items.push(`<li${attrs}>${m[4]}</li>`);
  }
  closeAll();
  return out.join("");
}

/** Convert .docx bytes to editor HTML. Async (entry inflate). */
export async function docxToHtml(bytes: Uint8Array): Promise<string> {
  const xml = await readZipEntry(bytes, "word/document.xml");
  if (!xml) throw new Error("word/document.xml not found in DOCX");
  const doc = new DOMParser().parseFromString(new TextDecoder().decode(xml), "application/xml");
  const body = doc.getElementsByTagNameNS(W, "body")[0];
  if (!body) return "";
  // Document-default spacing/line-height (styles.xml) — the fallback for any
  // paragraph that doesn't set its own, so the imported page count matches.
  let defaults: DocDefaults = {};
  const stylesXml = await readZipEntry(bytes, "word/styles.xml");
  if (stylesXml) {
    const stylesDoc = new DOMParser().parseFromString(new TextDecoder().decode(stylesXml), "application/xml");
    defaults = readDocDefaults(stylesDoc);
  }
  // Relationship-backed lookups, resolved up front (the only async parts):
  // inline images (rId → data URL), external hyperlink targets (rId → URL),
  // and real list numbering (numId → ilvl → numFmt). The sync paragraph/run
  // mappers then just look them up.
  const rels = await readRelationships(bytes);
  const images = await extractImageDataUrls(bytes, doc, rels);
  const links = hyperlinkTargets(rels);
  const numbering = await readNumbering(bytes);
  const blocks: string[] = [];
  for (const el of Array.from(body.children)) {
    if (el.localName === "p") blocks.push(paragraphToHtml(el, defaults, images, links, numbering));
    else if (el.localName === "tbl") blocks.push(tableToHtml(el, images, links));
    // skip sectPr etc.
  }
  return coalesceLists(blocks);
}

// ── Source page geometry (w:sectPr) ───────────────────────────────
export type DocxPageGeometry = {
  widthMm: number;
  heightMm: number;
  marginMm: { top: number; right: number; bottom: number; left: number };
};

/**
 * Read the source document's page size + margins from the LAST <w:sectPr>
 * (the body-level section properties — Word puts the final section's setup
 * there). Values are twips; converted twips → pt (/20) → mm (*25.4/72),
 * rounded to 1 decimal. Returns null when absent or malformed so callers can
 * keep their configured page setup.
 */
export async function docxPageGeometry(bytes: Uint8Array): Promise<DocxPageGeometry | null> {
  try {
    const xml = await readZipEntry(bytes, "word/document.xml");
    if (!xml) return null;
    const doc = new DOMParser().parseFromString(new TextDecoder().decode(xml), "application/xml");
    const sects = doc.getElementsByTagNameNS(W, "sectPr");
    if (!sects.length) return null;
    const sect = sects[sects.length - 1];
    const pgSz = wq(sect, "pgSz");
    const pgMar = wq(sect, "pgMar");
    if (!pgSz || !pgMar) return null;
    const twips = (el: Element, n: string): number | null => {
      const v = el.getAttributeNS(W, n) ?? el.getAttribute(`w:${n}`);
      return v != null && /^\d+$/.test(v) ? Number(v) : null;
    };
    const toMm = (tw: number) => Math.round(((tw / 20) * (25.4 / 72)) * 10) / 10;
    const w = twips(pgSz, "w");
    const h = twips(pgSz, "h");
    const top = twips(pgMar, "top");
    const right = twips(pgMar, "right");
    const bottom = twips(pgMar, "bottom");
    const left = twips(pgMar, "left");
    if (w == null || h == null || w <= 0 || h <= 0) return null;
    if (top == null || right == null || bottom == null || left == null) return null;
    // Sanity bounds: reject absurd page sizes (under 50mm / over 1200mm) and
    // margins that leave no content area.
    const widthMm = toMm(w);
    const heightMm = toMm(h);
    if (widthMm < 50 || widthMm > 1200 || heightMm < 50 || heightMm > 1200) return null;
    const marginMm = { top: toMm(top), right: toMm(right), bottom: toMm(bottom), left: toMm(left) };
    if (marginMm.left + marginMm.right >= widthMm || marginMm.top + marginMm.bottom >= heightMm) return null;
    return { widthMm, heightMm, marginMm };
  } catch {
    return null;
  }
}
