import type { PrintCss } from "../types";
import {
  A4_CONTENT_HEIGHT_PX,
  A4_PAGE_HEIGHT_PX,
  A4_PAGE_WIDTH_PX,
} from "./pageScale";

export type CreateA4PrintCssOptions = {
  margin?: string;
  fontFamily?: string;
  fontSize?: string;
  lineHeight?: string | number;
  textColor?: string;
  pageBackground?: string;
  pageBorderColor?: string;
  pageShadow?: string;
  showPageNumbers?: boolean;
};

export type PagedPreviewer = {
  preview: (
    content: string | HTMLElement,
    stylesheets: Array<string | Record<string, string>>,
    renderTo: HTMLElement,
  ) => Promise<{ total?: number | null }>;
  chunker?: {
    stop?: () => void;
    destroy?: () => void;
  };
  polisher?: {
    destroy?: () => void;
  };
};

export function createA4PrintCss(options: CreateA4PrintCssOptions = {}): string {
  const margin = options.margin ?? "1in 1.1in 1.2in 1.1in";
  const fontFamily =
    options.fontFamily ??
    '-apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif';
  const fontSize = options.fontSize ?? "11pt";
  const lineHeight = options.lineHeight ?? 1.55;
  const textColor = options.textColor ?? "#111827";
  const pageBackground = options.pageBackground ?? "#ffffff";
  const pageBorderColor = options.pageBorderColor ?? "#e5e7eb";
  const pageShadow =
    options.pageShadow ?? "0 2px 8px rgba(15, 23, 42, 0.04), 0 14px 36px rgba(15, 23, 42, 0.10)";
  const pageNumbers = options.showPageNumbers !== false
    ? `
    @bottom-center {
      content: "Page " counter(page) " of " counter(pages);
      font-family: ${fontFamily};
      font-size: 9pt;
      color: #6b7280;
      padding-top: 0.35in;
    }`
    : "";

  return `
  @page {
    size: A4;
    margin: ${margin};
    ${pageNumbers}
  }

  .pagedjs_pages {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 24px;
    padding: 0;
    zoom: var(--pagedly-page-scale, 1);
  }

  .pagedjs_page {
    width: ${A4_PAGE_WIDTH_PX}px;
    height: ${A4_PAGE_HEIGHT_PX}px;
    background: ${pageBackground};
    color: ${textColor};
    border: 1px solid ${pageBorderColor};
    border-radius: 4px;
    box-shadow: ${pageShadow};
    margin: 0 !important;
    font-family: ${fontFamily};
    font-size: ${fontSize};
    line-height: ${lineHeight};
  }

  .pagedjs_page_content {
    overflow: visible;
  }

  .pagedly-source-root {
    outline: none;
    min-height: 1px;
    overflow-wrap: anywhere;
  }

  .pagedly-source-root p { margin: 0 0 8pt; }
  .pagedly-source-root h1,
  .pagedly-source-root h2,
  .pagedly-source-root h3,
  .pagedly-source-root h4 {
    margin: 14pt 0 6pt;
    line-height: 1.25;
  }
  .pagedly-source-root h1 { font-size: 18pt; }
  .pagedly-source-root h2 { font-size: 14pt; }
  .pagedly-source-root h3 { font-size: 12pt; }
  .pagedly-source-root ul { list-style: disc; padding-left: 1.5em; margin: 6pt 0; }
  .pagedly-source-root ol { list-style: decimal; padding-left: 1.5em; margin: 6pt 0; }
  .pagedly-source-root li { margin: 2pt 0; overflow-wrap: anywhere; }
  .pagedly-source-root blockquote {
    border-left: 2px solid #d1d5db;
    margin: 8pt 0;
    padding-left: 10pt;
    color: #4b5563;
  }
  .pagedly-source-root table {
    width: 100%;
    table-layout: fixed;
    border-collapse: collapse;
    margin: 8pt 0;
  }
  .pagedly-source-root th,
  .pagedly-source-root td {
    border: 1px solid #d1d5db;
    padding: 4pt 7pt;
    text-align: left;
    vertical-align: top;
    overflow-wrap: anywhere;
  }
  .pagedly-source-root img {
    max-width: 100%;
    max-height: ${A4_CONTENT_HEIGHT_PX - 24}px;
    height: auto;
    object-fit: contain;
    border-radius: 3px;
    margin: 6pt 0;
  }
  /*
   * Break-inside rules are scoped to the elements paged.js actually
   * lays out (its rendered .pagedjs_page wrapper around .letter-body).
   * Applying them to .pagedly-source-root at the source level was wrong:
   * it also constrained the .letter-body container itself, leaving
   * paged.js with no way to split content across pages.
   * Match HRLETTER's proven selectors: direct children of .letter-body
   * inside a rendered page, excluding hidden section anchors.
   */
  .pagedjs_page .letter-body > p,
  .pagedjs_page .letter-body > h1,
  .pagedjs_page .letter-body > h2,
  .pagedjs_page .letter-body > h3,
  .pagedjs_page .letter-body > h4,
  .pagedjs_page .letter-body > div:not([data-section-anchor]),
  .pagedjs_page .letter-body > blockquote,
  .pagedjs_page .letter-body table,
  .pagedjs_page .letter-body figure,
  .pagedjs_page .letter-body img,
  .pagedjs_page .letter-body li {
    break-inside: avoid;
    page-break-inside: avoid;
  }

  /* Headings should stick with the next paragraph rather than being split. */
  .pagedjs_page .letter-body > h1,
  .pagedjs_page .letter-body > h2,
  .pagedjs_page .letter-body > h3,
  .pagedjs_page .letter-body > h4 {
    break-after: avoid;
    page-break-after: avoid;
  }

  .pagedly-source-root hr.letter-rule {
    border: none;
    border-top: 1px solid #d1d5db;
    margin: 14pt 0;
  }

  .pagedly-source-root .letterhead {
    margin-bottom: 18pt;
    text-align: center;
  }
  .pagedly-source-root .letterhead img {
    max-width: 100%;
    max-height: 120px;
  }

  .pagedly-source-root .signature-image {
    margin: 6pt 0;
  }
  .pagedly-source-root .signature-image img {
    max-height: 54px;
  }

  .pagedly-source-root .attachment-ref {
    color: #4b5563;
    font-style: italic;
  }

  .pagedly-source-root .attachments-section {
    margin-top: 18pt;
  }
  .pagedly-source-root .attachments-section h2 {
    padding-bottom: 4pt;
    border-bottom: 1px solid #d1d5db;
    margin-bottom: 8pt;
  }
  .pagedly-source-root .attachments-list {
    list-style: decimal;
    padding-left: 1.2em;
  }
  .pagedly-source-root .attachments-list .att-num {
    margin-left: 6pt;
    color: #6b7280;
    font-size: 9pt;
  }

  .pagedly-source-root .page-break-before {
    break-before: page;
    page-break-before: always;
  }

  @media (max-width: 640px) {
    .pagedjs_pages { gap: 18px; }
    .pagedjs_page {
      box-shadow: 0 4px 16px rgba(15, 23, 42, 0.10), 0 18px 44px rgba(15, 23, 42, 0.14);
    }
  }
`;
}

export function stylesheetsForPrintCss(printCss: PrintCss): Array<string | Record<string, string>> {
  if (Array.isArray(printCss)) return printCss;
  if (typeof printCss === "string") {
    return [{ "paged-html-editor://print.css": printCss }];
  }
  return [printCss];
}

export async function createPreviewer(): Promise<PagedPreviewer> {
  const { Previewer } = await import("pagedjs");
  return new Previewer() as PagedPreviewer;
}

export function destroyPreviewer(previewer: PagedPreviewer | null): void {
  if (!previewer) return;
  try {
    previewer.chunker?.stop?.();
    previewer.chunker?.destroy?.();
    previewer.polisher?.destroy?.();
  } catch {
    // paged.js cleanup should not mask editor state or unmount cleanup.
  }
}

export function createPaginationStagingHost(container: HTMLElement): HTMLElement {
  const host = document.createElement("div");
  const width = container.getBoundingClientRect().width || A4_PAGE_WIDTH_PX;
  host.setAttribute("aria-hidden", "true");
  Object.assign(host.style, {
    position: "absolute",
    left: "-100000px",
    top: "0",
    width: `${width}px`,
    minHeight: "1px",
    visibility: "hidden",
    pointerEvents: "none",
    overflow: "visible",
  });
  document.body.appendChild(host);
  return host;
}
