export type CursorState = {
  start: CursorPoint;
  end: CursorPoint;
};

export type CursorPoint = {
  ref: string;
  offset: number;
};

export function captureCursor(root: HTMLElement): CursorState | null {
  const sel = window.getSelection();
  if (!sel || sel.rangeCount === 0) return null;
  const range = sel.getRangeAt(0);
  const start = captureCursorPoint(root, range.startContainer, range.startOffset);
  if (!start) return null;
  const end = range.collapsed
    ? start
    : captureCursorPoint(root, range.endContainer, range.endOffset);
  return { start, end: end ?? start };
}

export function restoreCursor(
  root: HTMLElement,
  cursor: CursorState,
  editableRootSelector = ".pagedly-source-root",
): void {
  const start = findCursorPoint(root, cursor.start, editableRootSelector);
  const end = findCursorPoint(root, cursor.end, editableRootSelector);
  if (!start || !end) return;

  start.editableRoot?.focus({ preventScroll: true });
  const range = document.createRange();
  range.setStart(start.node, start.offset);
  range.setEnd(end.node, end.offset);
  const sel = window.getSelection();
  sel?.removeAllRanges();
  sel?.addRange(range);
}

export function positionLength(node: Node): number {
  if (isIgnoredPositionNode(node)) return 0;
  if (node.nodeType === Node.TEXT_NODE) return node.textContent?.length ?? 0;
  if (isAtomicPositionNode(node)) return 1;
  let total = 0;
  for (const child of Array.from(node.childNodes)) {
    total += positionLength(child);
  }
  return total;
}

export function isAtomicPositionNode(node: Node): boolean {
  if (node.nodeType !== Node.ELEMENT_NODE) return false;
  return ["BR", "IMG", "HR"].includes((node as HTMLElement).tagName);
}

function captureCursorPoint(
  root: HTMLElement,
  target: Node,
  targetOffset: number,
): CursorPoint | null {
  if (!root.contains(target)) return null;
  let el = nodeElement(target);
  let refEl: HTMLElement | null = null;
  while (el && el !== root) {
    if (el.hasAttribute("data-pagedly-ref")) {
      refEl = el;
      break;
    }
    el = el.parentElement;
  }
  if (!refEl) return null;

  const ref = refEl.getAttribute("data-pagedly-ref");
  if (!ref) return null;

  let offset = positionOffsetWithin(refEl, target, targetOffset);
  const matches = Array.from(
    root.querySelectorAll<HTMLElement>(`[data-pagedly-ref="${cssEscape(ref)}"]`),
  );
  for (const match of matches) {
    if (match === refEl) break;
    offset += positionLength(match);
  }
  return { ref, offset };
}

function positionOffsetWithin(root: HTMLElement, target: Node, targetOffset: number): number {
  let total = 0;
  let found = false;

  const visit = (node: Node): void => {
    if (found || isIgnoredPositionNode(node)) return;
    if (node === target) {
      if (node.nodeType === Node.TEXT_NODE) {
        total += Math.max(0, Math.min(targetOffset, node.textContent?.length ?? 0));
      } else {
        const children = Array.from(node.childNodes).slice(0, targetOffset);
        total += children.reduce((sum, childNode) => sum + positionLength(childNode), 0);
      }
      found = true;
      return;
    }

    if (node.nodeType === Node.TEXT_NODE || isAtomicPositionNode(node)) {
      total += positionLength(node);
      return;
    }

    for (const childNode of Array.from(node.childNodes)) visit(childNode);
  };

  visit(root);
  return total;
}

function findCursorPoint(
  root: HTMLElement,
  cursor: CursorPoint,
  editableRootSelector: string,
): { node: Node; offset: number; editableRoot: HTMLElement | null } | null {
  const matches = Array.from(
    root.querySelectorAll<HTMLElement>(`[data-pagedly-ref="${cssEscape(cursor.ref)}"]`),
  );
  if (matches.length === 0) return null;

  let remaining = cursor.offset;
  for (const match of matches) {
    const len = positionLength(match);
    if (remaining <= len) {
      const point = pointAtPositionOffset(match, remaining);
      return {
        ...point,
        editableRoot: editableRootForCursorPoint(match, editableRootSelector),
      };
    }
    remaining -= len;
  }

  const last = matches[matches.length - 1];
  return {
    node: last,
    offset: last.childNodes.length,
    editableRoot: editableRootForCursorPoint(last, editableRootSelector),
  };
}

function editableRootForCursorPoint(
  node: HTMLElement,
  editableRootSelector: string,
): HTMLElement | null {
  try {
    const configuredRoot = node.closest<HTMLElement>(editableRootSelector);
    if (configuredRoot) return configuredRoot;
  } catch {
    // Ignore invalid selectors; fall through to the built-in defaults.
  }
  return (
    node.closest<HTMLElement>(".pagedly-source-root") ??
    node.closest<HTMLElement>(".letter-body") ??
    node.closest<HTMLElement>(".pagedjs_page_content")
  );
}

function pointAtPositionOffset(root: HTMLElement, offset: number): { node: Node; offset: number } {
  let remaining = Math.max(0, offset);
  const beforeNode = (node: Node) => ({
    node: node.parentNode ?? root,
    offset: node.parentNode ? Array.prototype.indexOf.call(node.parentNode.childNodes, node) : 0,
  });
  const afterNode = (node: Node) => ({
    node: node.parentNode ?? root,
    offset: node.parentNode
      ? Array.prototype.indexOf.call(node.parentNode.childNodes, node) + 1
      : 0,
  });

  const find = (node: Node): { node: Node; offset: number } | null => {
    if (isIgnoredPositionNode(node)) return null;
    if (node.nodeType === Node.TEXT_NODE) {
      const len = node.textContent?.length ?? 0;
      if (remaining <= len) return { node, offset: remaining };
      remaining -= len;
      return null;
    }
    if (isAtomicPositionNode(node)) {
      if (remaining === 0) return beforeNode(node);
      remaining -= 1;
      if (remaining === 0) return afterNode(node);
      return null;
    }
    for (const child of Array.from(node.childNodes)) {
      const found = find(child);
      if (found) return found;
    }
    return null;
  };

  return find(root) ?? { node: root, offset: root.childNodes.length };
}

function isIgnoredPositionNode(node: Node): boolean {
  if (node.nodeType !== Node.ELEMENT_NODE) return false;
  const el = node as HTMLElement;
  return (
    el.getAttribute("data-pagedly-readonly-source") === "true" ||
    el.getAttribute("aria-hidden") === "true" ||
    el.style.display === "none"
  );
}

function nodeElement(node: Node): HTMLElement | null {
  return node.nodeType === Node.TEXT_NODE
    ? (node.parentElement as HTMLElement | null)
    : (node as HTMLElement | null);
}

function cssEscape(value: string): string {
  if (typeof CSS !== "undefined" && typeof CSS.escape === "function") {
    return CSS.escape(value);
  }
  return value.replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}
