// Markdown-style "input rules" + smart typography + autolink.
//
// These are PURE matchers (block / typography / inline) plus a small set of
// helpers. The DOM application lives in Editor.tsx, which owns the trusted
// command path (formatBlock / list / blockquote) so block transforms reflow
// correctly. Everything here is engine-agnostic and unit-testable.
//
// Design rules:
//  - Block rules fire on Space (and the code-fence on the 3rd backtick) when
//    the typed prefix is the WHOLE text from block-start to the caret.
//  - Inline emphasis fires when the user types the CLOSING delimiter.
//  - Typography fires on the triggering character (2nd dash, 3rd dot, ')').
//  - Nothing fires inside <pre>/<code> (the caller checks context).

export type MarkdownBlockCommand =
  | { command: "formatBlock"; value: string }
  | { command: "insertUnorderedList" }
  | { command: "insertOrderedList" }
  | { command: "insertChecklist" }
  | { command: "toggleBlockquote" }
  | { command: "formatCodeBlock" };

/**
 * Match a block-level markdown prefix. `before` is the text from the block
 * start to the caret; `data` is the character being inserted (" " for most,
 * "`" for the code fence). Returns the command to run, or null.
 */
export function matchBlockRule(
  before: string,
  data: string,
): MarkdownBlockCommand | null {
  // Code fence: ``` at line start (caret after the 2nd backtick, typing 3rd).
  if (data === "`") {
    if (before === "``") return { command: "formatCodeBlock" };
    return null;
  }
  if (data !== " ") return null;

  // Headings: # … ###### at line start.
  const heading = /^(#{1,6})$/.exec(before);
  if (heading) {
    return { command: "formatBlock", value: `h${heading[1].length}` };
  }
  // Bullet list: -, *, +
  if (/^[-*+]$/.test(before)) return { command: "insertUnorderedList" };
  // Numbered list: 1.  2)  etc.
  if (/^\d{1,9}[.)]$/.test(before)) return { command: "insertOrderedList" };
  // Checklist: [], [ ], [x], [X]
  if (/^\[[ xX]?\]$/.test(before)) return { command: "insertChecklist" };
  // Blockquote: >
  if (before === ">") return { command: "toggleBlockquote" };
  return null;
}

/**
 * Smart-typography replacement. `before` is the text before the caret (within
 * the caret's text node); `data` is the character being typed. Returns how many
 * chars to remove before the caret and what to insert in place of `data`.
 */
export function matchTypography(
  before: string,
  data: string,
): { removeBefore: number; insert: string } | null {
  // Em dash: "--" + next char handled separately; here we collapse on the 2nd.
  if (data === "-" && /-$/.test(before) && !/--$/.test(before)) {
    return { removeBefore: 1, insert: "—" }; // —
  }
  // Ellipsis: "..." -> …  (fires on the 3rd dot)
  if (data === "." && /\.\.$/.test(before)) {
    return { removeBefore: 2, insert: "…" }; // …
  }
  // Symbols on closing paren.
  if (data === ")") {
    if (/\(c$/i.test(before)) return { removeBefore: 2, insert: "©" }; // ©
    if (/\(r$/i.test(before)) return { removeBefore: 2, insert: "®" }; // ®
    if (/\(tm$/i.test(before)) return { removeBefore: 3, insert: "™" }; // ™
  }
  return null;
}

const escapeHtml = (s: string): string =>
  s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");

/**
 * Inline emphasis. Fires when `data` is the closing delimiter. `before` is the
 * text before the caret in the caret's text node. Returns how many chars to
 * remove before the caret (the opener + content) and the HTML to insert (the
 * wrapped run). The typed closing delimiter is NOT inserted.
 */
export function matchInline(
  before: string,
  data: string,
): { removeBefore: number; html: string } | null {
  // Inline code: `code`
  if (data === "`") {
    const m = /`([^`]+)$/.exec(before);
    if (m) {
      return {
        removeBefore: m[1].length + 1,
        html: `<code>${escapeHtml(m[1])}</code>`,
      };
    }
    return null;
  }
  if (data === "*") {
    // Bold: **text**  (caret after "**text*", typing final "*")
    const bold = /\*\*([^*]+)\*$/.exec(before);
    if (bold) {
      return {
        removeBefore: bold[1].length + 3,
        html: `<strong>${escapeHtml(bold[1])}</strong>`,
      };
    }
    // Italic: *text*  (single star, opener not preceded by another star)
    const italic = /(?:^|[^*])\*([^*]+)$/.exec(before);
    if (italic) {
      return {
        removeBefore: italic[1].length + 1,
        html: `<em>${escapeHtml(italic[1])}</em>`,
      };
    }
    return null;
  }
  if (data === "_") {
    // Italic: _text_
    const italic = /(?:^|[^_])_([^_]+)$/.exec(before);
    if (italic) {
      return {
        removeBefore: italic[1].length + 1,
        html: `<em>${escapeHtml(italic[1])}</em>`,
      };
    }
    return null;
  }
  if (data === "~") {
    // Strikethrough: ~~text~~  (caret after "~~text~", typing final "~")
    const strike = /~~([^~]+)~$/.exec(before);
    if (strike) {
      return {
        removeBefore: strike[1].length + 3,
        html: `<s>${escapeHtml(strike[1])}</s>`,
      };
    }
    return null;
  }
  return null;
}

const URL_RE = /(https?:\/\/[^\s]+|www\.[^\s]+)$/i;

/**
 * Autolink: when a word boundary (space) is typed after a URL token, return the
 * token + its char length so the caller can wrap it in an anchor. Trailing
 * punctuation is excluded from the link.
 */
export function matchAutoLink(
  before: string,
): { url: string; href: string; length: number } | null {
  const m = URL_RE.exec(before);
  if (!m) return null;
  let token = m[1];
  // Don't swallow trailing sentence punctuation (it stays as literal text).
  while (token.length && /[.,;:!?)\]}'"]$/.test(token)) {
    token = token.slice(0, -1);
  }
  if (token.length < 4) return null;
  const href = /^www\./i.test(token) ? `https://${token}` : token;
  return { url: token, href, length: token.length };
}
