import DOMPurify from "dompurify";

import { wrapLooseTopLevelContent } from "./reconstruct";

export type SanitizePastedHtmlOptions = {
  sanitizeHtml?: (dirty: string) => string;
  plainText?: string;
};

export function sanitizePastedHtml(html: string, options: SanitizePastedHtmlOptions = {}): string {
  if (typeof document === "undefined") return html;

  const parsed = new DOMParser().parseFromString(html, "text/html");
  normalizeOfficePaste(parsed.body);
  convertWordListParagraphs(parsed.body);

  const bodyHtml = parsed.body.innerHTML || html;
  const sanitize = options.sanitizeHtml ?? defaultSanitizeHtml;
  const sanitized = sanitize(bodyHtml);
  const doc = new DOMParser().parseFromString(`<div>${sanitized}</div>`, "text/html");
  const root = doc.body.firstElementChild as HTMLElement | null;
  if (!root) return "";

  for (const el of Array.from(root.querySelectorAll<HTMLElement>("*"))) {
    scrubPasteAttributes(el);
  }

  normalizePastedBlockStructure(root);

  if (shouldUsePlainTextVersion(options.plainText, root)) {
    return plainTextToEditorHtml(options.plainText ?? "");
  }

  return root.innerHTML;
}

export function plainTextToEditorHtml(text: string): string {
  if (!text) return "";
  if (!/[\r\n]/.test(text)) return escapeHtml(text);
  const paragraphs = text
    .split(/\r\n|\r|\n/)
    .map((line) => line.replace(/^[ \t]+|[ \t]+$/g, ""))
    .filter(Boolean)
    .map((line) => `<p>${escapeHtml(line)}</p>`);
  return paragraphs.join("");
}

export function defaultSanitizeHtml(dirty: string): string {
  if (typeof window === "undefined") return dirty;
  return DOMPurify.sanitize(dirty, {
    ALLOWED_TAGS: [
      "p",
      "br",
      "strong",
      "b",
      "em",
      "i",
      "u",
      "s",
      "strike",
      "sub",
      "sup",
      "h1",
      "h2",
      "h3",
      "h4",
      "ul",
      "ol",
      "li",
      "blockquote",
      "a",
      "table",
      "thead",
      "tbody",
      "tr",
      "th",
      "td",
      "hr",
      "span",
      "div",
      "img",
      "figure",
      "figcaption",
      "section",
      "header",
      "footer",
      "template",
    ],
    ALLOWED_ATTR: [
      "href",
      "target",
      "rel",
      "colspan",
      "rowspan",
      "src",
      "alt",
      "title",
      "width",
      "height",
      "class",
      "style",
      "data-generated-chrome",
    ],
    ALLOW_DATA_ATTR: false,
    KEEP_CONTENT: true,
    ALLOWED_URI_REGEXP:
      /^(?:https?:|mailto:|tel:|#|\/(?!\/)|blob:|data:image\/(?:png|jpeg|jpg|gif|webp);base64,)/i,
  });
}

function normalizeOfficePaste(root: HTMLElement): void {
  const comments = document.createTreeWalker(root, NodeFilter.SHOW_COMMENT);
  const toRemove: Node[] = [];
  let comment = comments.nextNode();
  while (comment) {
    toRemove.push(comment);
    comment = comments.nextNode();
  }
  for (const node of toRemove) node.parentNode?.removeChild(node);

  for (const selector of ["style", "meta", "link", "script", "xml"]) {
    for (const el of Array.from(root.querySelectorAll(selector))) el.remove();
  }

  for (const el of Array.from(root.querySelectorAll<HTMLElement>("*"))) {
    const tag = el.tagName.toLowerCase();
    if (tag.includes(":")) {
      el.replaceWith(...Array.from(el.childNodes));
    }
  }
}

function convertWordListParagraphs(root: HTMLElement): void {
  for (const child of Array.from(root.children) as HTMLElement[]) {
    convertWordListParagraphs(child);
  }

  let currentList: HTMLOListElement | HTMLUListElement | null = null;
  let currentKind: "ol" | "ul" | null = null;
  for (const node of Array.from(root.childNodes)) {
    if (node.nodeType !== Node.ELEMENT_NODE || !isWordListParagraph(node as HTMLElement)) {
      currentList = null;
      currentKind = null;
      continue;
    }

    const paragraph = node as HTMLElement;
    const kind = wordListKind(paragraph);
    if (!currentList || currentKind !== kind) {
      currentList = document.createElement(kind);
      currentKind = kind;
      root.insertBefore(currentList, paragraph);
    }
    const li = document.createElement("li");
    li.innerHTML = wordListItemHtml(paragraph);
    currentList.appendChild(li);
    paragraph.remove();
  }
}

function isWordListParagraph(el: HTMLElement): boolean {
  if (!["P", "DIV"].includes(el.tagName)) return false;
  const className = el.getAttribute("class") ?? "";
  const style = el.getAttribute("style") ?? "";
  return /MsoListParagraph/i.test(className) || /mso-list\s*:/i.test(style);
}

function wordListKind(el: HTMLElement): "ol" | "ul" {
  const text = (el.textContent ?? "").trim();
  return /^(?:\d+|[a-z]|[ivxlcdm]+)[.)]\s+/i.test(text) ? "ol" : "ul";
}

function wordListItemHtml(el: HTMLElement): string {
  const text = (el.textContent ?? "")
    .replace(/^\s*(?:[\u2022\u00b7\u25cf\u25cb\u25aa\-\*o]|\d+|[a-z]|[ivxlcdm]+)[.)]?\s+/i, "")
    .trim();
  return escapeHtml(text);
}

function scrubPasteAttributes(el: HTMLElement): void {
  const tag = el.tagName;
  const allowed = new Set<string>();
  const textAlign = safeTextAlignFromStyle(el.getAttribute("style") ?? "");

  if (tag === "A") {
    allowed.add("href");
    allowed.add("target");
    allowed.add("rel");
  } else if (tag === "IMG") {
    allowed.add("src");
    allowed.add("alt");
    allowed.add("title");
    allowed.add("width");
    allowed.add("height");
  } else if (tag === "TD" || tag === "TH") {
    allowed.add("colspan");
    allowed.add("rowspan");
  }

  if (textAlign && /^(P|DIV|H1|H2|H3|H4|LI|TD|TH)$/.test(tag)) {
    allowed.add("style");
  }

  for (const attr of Array.from(el.attributes)) {
    if (!allowed.has(attr.name)) el.removeAttribute(attr.name);
  }
  if (textAlign) el.setAttribute("style", `text-align: ${textAlign};`);
}

function normalizePastedBlockStructure(root: HTMLElement): void {
  splitSimpleBlocksOnLineBreaks(root);
  convertSimpleDivsToParagraphs(root);
  wrapLooseTopLevelContent(root);
  removeEmptyTopLevelBlocks(root);
}

function splitSimpleBlocksOnLineBreaks(root: HTMLElement): void {
  for (const child of Array.from(root.children) as HTMLElement[]) {
    splitSimpleBlocksOnLineBreaks(child);
  }

  for (const block of Array.from(root.children) as HTMLElement[]) {
    if (!/^(P|DIV)$/.test(block.tagName)) continue;
    if (block.querySelector("table, ul, ol, li, blockquote, img, figure")) continue;
    const parts = htmlPartsSplitByHardBreaks(block);
    if (parts.length <= 1) continue;
    for (const part of parts) {
      const next = root.ownerDocument.createElement(block.tagName.toLowerCase());
      for (const attr of Array.from(block.attributes)) {
        next.setAttribute(attr.name, attr.value);
      }
      next.innerHTML = part;
      root.insertBefore(next, block);
    }
    block.remove();
  }
}

function htmlPartsSplitByHardBreaks(block: HTMLElement): string[] {
  const parts: string[] = [];
  let current: string[] = [];
  let pendingBreak = false;

  const flush = () => {
    const html = current.join("").trim();
    if (html) parts.push(html);
    current = [];
    pendingBreak = false;
  };

  for (const node of Array.from(block.childNodes)) {
    if (node instanceof HTMLBRElement) {
      if (pendingBreak) flush();
      else pendingBreak = true;
      continue;
    }
    if (pendingBreak) {
      current.push("<br>");
      pendingBreak = false;
    }
    current.push(nodeToHtml(node));
  }
  flush();
  return parts;
}

function nodeToHtml(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return escapeHtml(node.textContent ?? "");
  if (node.nodeType === Node.ELEMENT_NODE) return (node as HTMLElement).outerHTML;
  return "";
}

function convertSimpleDivsToParagraphs(root: HTMLElement): void {
  for (const child of Array.from(root.children) as HTMLElement[]) {
    convertSimpleDivsToParagraphs(child);
  }

  for (const div of Array.from(root.children) as HTMLElement[]) {
    if (div.tagName !== "DIV") continue;
    if (div.querySelector("p, h1, h2, h3, h4, ul, ol, table, blockquote, figure, section, header, footer")) {
      continue;
    }
    const paragraph = root.ownerDocument.createElement("p");
    for (const attr of Array.from(div.attributes)) paragraph.setAttribute(attr.name, attr.value);
    paragraph.innerHTML = div.innerHTML;
    div.replaceWith(paragraph);
  }
}

function removeEmptyTopLevelBlocks(root: HTMLElement): void {
  for (const child of Array.from(root.children) as HTMLElement[]) {
    if (!/^(P|DIV)$/.test(child.tagName)) continue;
    if ((child.textContent ?? "").trim()) continue;
    if (child.querySelector("img, br, hr, table")) continue;
    child.remove();
  }
}

function shouldUsePlainTextVersion(plainText: string | undefined, root: HTMLElement): boolean {
  if (!plainText || !/[\r\n]/.test(plainText)) return false;
  if (root.querySelector("table, ul, ol, li, img, figure")) return false;
  return normalizeClipboardText(blockTextForClipboardComparison(root)) === normalizeClipboardText(plainText);
}

function normalizeClipboardText(text: string): string {
  return text.replace(/\u00a0/g, " ").replace(/\s+/g, " ").trim();
}

function blockTextForClipboardComparison(root: HTMLElement): string {
  return Array.from(root.childNodes).map(textForClipboardNode).join("");
}

function textForClipboardNode(node: Node): string {
  if (node.nodeType === Node.TEXT_NODE) return node.textContent ?? "";
  if (!(node instanceof HTMLElement)) return "";
  if (node instanceof HTMLBRElement) return "\n";
  const text = Array.from(node.childNodes).map(textForClipboardNode).join("");
  return isBlockPasteElement(node) ? `${text}\n` : text;
}

function isBlockPasteElement(node: HTMLElement): boolean {
  return /^(P|DIV|H1|H2|H3|H4|BLOCKQUOTE|LI|TABLE|UL|OL|SECTION|ARTICLE|HEADER|FOOTER)$/.test(node.tagName);
}

function safeTextAlignFromStyle(style: string): "left" | "center" | "right" | "justify" | "" {
  const match = /text-align\s*:\s*(left|center|right|justify)\b/i.exec(style);
  return (match?.[1]?.toLowerCase() as "left" | "center" | "right" | "justify" | undefined) ?? "";
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
