import type { CreateA4PrintCssOptions } from "../paged/render";
import { createA4PrintCss } from "../paged/render";

export function createPagedLetterPrintCss(options: CreateA4PrintCssOptions = {}): string {
  return createA4PrintCss({
    fontFamily:
      options.fontFamily ??
      '"Geist Variable", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif',
    fontSize: options.fontSize ?? "11pt",
    lineHeight: options.lineHeight ?? 1.55,
    textColor: options.textColor ?? "#0f172a",
    pageBackground: options.pageBackground ?? "#ffffff",
    pageBorderColor: options.pageBorderColor ?? "#e2e8f0",
    pageShadow:
      options.pageShadow ??
      "0 2px 8px rgba(0,0,0,0.04), 0 6px 24px rgba(0,0,0,0.06)",
    margin: options.margin ?? "1in 1.1in 1.2in 1.1in",
    showPageNumbers: options.showPageNumbers,
  });
}
