import {
  forwardRef,
  useCallback,
  useEffect,
  useImperativeHandle,
  useRef,
} from "react";

import { DEFAULT_TOOLBAR_STATE } from "./Toolbar";
import { Editor } from "./Editor";
import type { EditorHandle } from "./types";
import {
  applySectionHtmlToDraft,
  buildAttachmentsBlock,
  buildLetterEditorHtml,
  letterheadHtml,
  sanitizePagedLetterHtml,
  signatureImageHtml,
  splitLetterEditorHtml,
} from "./letter/sourceHtml";

// Local copy — same as letter/sourceHtml's private helper. Used to
// escape signatory name / title for safe innerHTML injection.
function escapeHtml(v: string): string {
  return v
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}
import type {
  LetterDraft,
  LetterEditorChange,
  LetterEditorProps,
} from "./letter/types";

/**
 * The letter editor is now a thin wrapper around Editor. TipTap
 * owns the document state; we keep responsibility for section management
 * (anchor markers → per-section html) on the way in and out.
 *
 * Chrome (letterhead, signature image, attachments) is NOT rendered in the
 * editing view — TipTap edits the body content directly. Hosts that want a
 * paged.js preview of the full letter should call
 * `buildPagedLetterFullHtml(draft)` from `./letter/sourceHtml` and feed the
 * result to paged.js separately.
 */
export const LetterEditor = forwardRef<EditorHandle, LetterEditorProps>(
  function LetterEditor(
    {
      draft,
      printCss: _printCss,
      className,
      canvasClassName,
      toolbar = true,
      toolbarPosition = "sticky",
      toolbarLayout = "full",
      viewMode,
      editorRef,
      actionsRef,
      onChange,
      onDraftChange,
      onSectionChange,
      onSave,
      autoSave,
      autoSaveDelayMs,
      readOnly,
      findPlaceholder = "Find in letter",
      reflowDelayMs,
      realtimePagination,
      pageHeaderHtml,
      pageFooterHtml,
      showPageNumbers,
      pasteFormatting,
      features,
      labels,
      aiProvider,
      suggesting,
      commands,
      pageSize,
      pageOrientation,
      pageMargin,
      documentMetrics,
      onDocumentMetricsChange,
      watermark,
      runningHead,
      differentFirstPage,
      placeholder,
      onCommentAdd,
      onCommentClick,
    },
    ref,
  ) {
    const innerRef = useRef<EditorHandle | null>(null);
    const lastChangeRef = useRef<LetterEditorChange | null>(null);

    // The host draft seeds the editor's INITIAL content. The editor is
    // uncontrolled after mount: ContentEditableEditor seeds its DOM from
    // `html` once (useEffect([])) and never re-seeds, so re-deriving
    // editorHtml on later renders only feeds the first paint + imperative
    // reads (flush). Edits flow OUT via onChange (commitFullHtml); the
    // host re-render does NOT rebuild the editor DOM — which is what makes
    // cross-section merges caret-safe (see BUGS_AND_FIXES).
    const liveDraftRef = useRef(draft);
    liveDraftRef.current = draft;
    const editorHtml = buildLetterEditorHtml(draft);

    // Print chrome injection: before window.print() fires, inject the
    // draft's letterhead / signature / attachments into the editor DOM
    // so they appear on the printed output. After print, remove them.
    //
    // Necessary because the editor only edits the BODY content; the
    // chrome (letterhead image, signature image, signatory text,
    // attachments page) lives on draft.employer.*.
    useEffect(() => {
      const onBeforePrint = () => {
        const d = liveDraftRef.current;
        // Find all page divs that will be printed.
        const pages = Array.from(
          document.querySelectorAll<HTMLElement>(".pagedly-ce-page"),
        );
        if (pages.length === 0) return;

        // Letterhead: prepend to FIRST page only.
        const letterhead = letterheadHtml(d);
        if (letterhead) {
          const wrap = document.createElement("div");
          wrap.className = "pagedly-print-chrome pagedly-print-chrome--letterhead";
          wrap.innerHTML = letterhead;
          pages[0].insertBefore(wrap, pages[0].firstChild);
        }

        // Signature image + signatory text: append to LAST page.
        const signature = signatureImageHtml(d);
        const sigName = d.employer?.signatoryName ?? "";
        const sigTitle = d.employer?.signatoryTitle ?? "";
        if (signature || sigName) {
          const wrap = document.createElement("div");
          wrap.className = "pagedly-print-chrome pagedly-print-chrome--signature";
          wrap.innerHTML = `${signature}${
            sigName
              ? `<div class="pagedly-print-signatory"><div>${escapeHtml(sigName)}</div>${
                  sigTitle
                    ? `<div class="pagedly-print-signatory-title">${escapeHtml(sigTitle)}</div>`
                    : ""
                }</div>`
              : ""
          }`;
          pages[pages.length - 1].appendChild(wrap);
        }

        // Attachments: append as a separate block. The CSS uses
        // page-break-before to put it on its own physical sheet.
        const attachments = buildAttachmentsBlock(d);
        if (attachments) {
          const wrap = document.createElement("div");
          wrap.className = "pagedly-print-chrome pagedly-print-chrome--attachments";
          wrap.innerHTML = attachments;
          pages[pages.length - 1].appendChild(wrap);
        }
      };
      const onAfterPrint = () => {
        for (const node of Array.from(
          document.querySelectorAll(".pagedly-print-chrome"),
        )) {
          node.parentNode?.removeChild(node);
        }
      };
      window.addEventListener("beforeprint", onBeforePrint);
      window.addEventListener("afterprint", onAfterPrint);
      return () => {
        window.removeEventListener("beforeprint", onBeforePrint);
        window.removeEventListener("afterprint", onAfterPrint);
      };
    }, []);

    useImperativeHandle(
      ref,
      (): EditorHandle => ({
        focus: () => innerRef.current?.focus(),
        reflow: () => innerRef.current?.reflow() ?? Promise.resolve(),
        flush: () => innerRef.current?.flush() ?? Promise.resolve(editorHtml),
        undo: () => innerRef.current?.undo(),
        redo: () => innerRef.current?.redo(),
        selectAll: () => innerRef.current?.selectAll(),
        openFind: () => innerRef.current?.openFind(),
        closeFind: () => innerRef.current?.closeFind(),
        runCommand: (command, value) => innerRef.current?.runCommand(command, value),
        insertHtml: (html) => innerRef.current?.insertHtml(html),
        setHtml: (html) => innerRef.current?.setHtml?.(html),
        getBlocks: () => innerRef.current?.getBlocks?.() ?? [],
        replaceBlock: (pid, html) => innerRef.current?.replaceBlock?.(pid, html) ?? false,
        insertImage: (src, alt) => innerRef.current?.insertImage(src, alt),
        requestImageInsert: () => innerRef.current?.requestImageInsert() ?? Promise.resolve(),
        getState: () => innerRef.current?.getState() ?? DEFAULT_TOOLBAR_STATE,
        subscribe: (listener) => {
          if (innerRef.current) return innerRef.current.subscribe(listener);
          listener(DEFAULT_TOOLBAR_STATE);
          return () => undefined;
        },
        downloadPdf: (options) => innerRef.current?.downloadPdf?.(options),
      }),
      [editorHtml],
    );

    const commitFullHtml = useCallback(
      (fullHtml: string): LetterEditorChange => {
        const currentDraft = liveDraftRef.current;
        const parsed = splitLetterEditorHtml(fullHtml, currentDraft.sections);
        const nextDraft = applySectionHtmlToDraft(currentDraft, parsed.sections);
        const change: LetterEditorChange = {
          fullHtml,
          bodyHtml: parsed.bodyHtml,
          sections: parsed.sections,
          draft: nextDraft,
        };

        liveDraftRef.current = nextDraft;

        for (const section of currentDraft.sections) {
          if (!Object.prototype.hasOwnProperty.call(parsed.sections, section.id)) continue;
          const nextHtml = parsed.sections[section.id] ?? "";
          if (nextHtml !== section.html) {
            onSectionChange?.(currentDraft.id, section.id, nextHtml);
          }
        }

        onDraftChange?.(nextDraft);
        onChange?.(change);
        lastChangeRef.current = change;
        return change;
      },
      [onChange, onDraftChange, onSectionChange],
    );

    const setInnerRef = useCallback(
      (handle: EditorHandle | null) => {
        innerRef.current = handle;
        if (editorRef) editorRef.current = handle;
      },
      [editorRef],
    );

    return (
      <Editor
        ref={setInnerRef}
        html={editorHtml}
        onChange={commitFullHtml}
        onSave={async (fullHtml) => {
          const change = lastChangeRef.current?.fullHtml === fullHtml
            ? lastChangeRef.current
            : commitFullHtml(fullHtml);
          await onSave?.(change);
        }}
        // onSave only fires through the autoSave debounce, so default it ON when
        // a host supplies onSave (pass autoSave={false} to drive saving yourself).
        autoSave={autoSave ?? (onSave ? true : undefined)}
        autoSaveDelayMs={autoSaveDelayMs}
        readOnly={readOnly}
        findPlaceholder={findPlaceholder}
        sanitizeHtml={sanitizePagedLetterHtml}
        toolbar={toolbar}
        toolbarPosition={toolbarPosition}
        toolbarLayout={toolbarLayout}
        viewMode={viewMode}
        className={["pagedly-editor--letter", className].filter(Boolean).join(" ")}
        canvasClassName={canvasClassName}
        actionsRef={actionsRef}
        reflowDelayMs={reflowDelayMs}
        realtimePagination={realtimePagination}
        pageHeaderHtml={pageHeaderHtml}
        pageFooterHtml={pageFooterHtml}
        showPageNumbers={showPageNumbers}
        pasteFormatting={pasteFormatting}
        features={features}
        labels={labels}
        aiProvider={aiProvider}
        suggesting={suggesting}
        commands={commands}
        pageSize={pageSize}
        pageOrientation={pageOrientation}
        pageMargin={pageMargin}
        documentMetrics={documentMetrics}
        onDocumentMetricsChange={onDocumentMetricsChange}
        watermark={watermark}
        runningHead={runningHead}
        differentFirstPage={differentFirstPage}
        placeholder={placeholder}
        onCommentAdd={onCommentAdd}
        onCommentClick={onCommentClick}
      />
    );
  },
);

export type { LetterDraft, LetterEditorChange, LetterEditorProps };
